                private static void ValidatePackResources()
                {
                    AssertEqual(
                        "External SDK pack resource text",
                        ReadPackResourceText(new Uri("Assets/ExternalResource.txt", UriKind.Relative)),
                        "external SDK relative Resource stream text");
                    AssertEqual(
                        "External SDK pack resource text",
                        ReadPackResourceText(new Uri("pack://application:,,,/Assets/ExternalResource.txt", UriKind.Absolute)),
                        "external SDK absolute pack Resource stream text");
                    AssertEqual(
                        "External SDK copied content text",
                        ReadPackContentText(new Uri("Assets/ExternalContent.txt", UriKind.Relative)),
                        "external SDK relative Content stream text");
                    AssertEqual(
                        "External SDK copied content text",
                        ReadPackContentText(new Uri("pack://application:,,,/Assets/ExternalContent.txt", UriKind.Absolute)),
                        "external SDK absolute pack Content stream text");
                    AssertEqual(
                        "External SDK copied content text",
                        ReadPackRemoteText(new Uri("Assets/ExternalContent.txt", UriKind.Relative)),
                        "external SDK relative Remote stream text");
                    AssertEqual(
                        "External SDK copied content text",
                        ReadPackRemoteText(new Uri("pack://siteoforigin:,,,/Assets/ExternalContent.txt", UriKind.Absolute)),
                        "external SDK absolute pack Remote stream text");
                }

