                private static void ValidateBindings(MainWindow window)
                {
                    var converterText = RequireType<TextBlock>(
                        window.FindName("ExternalConverterText"),
                        "external SDK converter text block");
                    AssertEqual("ALPHA:converted", converterText.Text, "external SDK value converter output");

                    var multiBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalMultiBindingText"),
                        "external SDK multibinding text block");
                    AssertEqual("Alpha|Framework", multiBindingText.Text, "external SDK multibinding converter output");
                    var multiBindingExpression = BindingOperations.GetMultiBindingExpression(
                        multiBindingText,
                        TextBlock.TextProperty);
                    if (multiBindingExpression is null)
                    {
                        throw new InvalidOperationException("Expected external SDK MultiBindingExpression.");
                    }

                    AssertEqual(2, multiBindingExpression.ParentMultiBinding.Bindings.Count, "external SDK multibinding child binding count");

                    var priorityBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalPriorityBindingText"),
                        "external SDK priority binding text block");
                    AssertEqual("Framework", priorityBindingText.Text, "external SDK priority binding fallback output");
                    var priorityBindingExpression = BindingOperations.GetPriorityBindingExpression(
                        priorityBindingText,
                        TextBlock.TextProperty);
                    if (priorityBindingExpression is null)
                    {
                        throw new InvalidOperationException("Expected external SDK PriorityBindingExpression.");
                    }

                    AssertEqual(2, priorityBindingExpression.ParentPriorityBinding.Bindings.Count, "external SDK priority binding child binding count");

                    var fallbackBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalFallbackBindingText"),
                        "external SDK fallback binding text block");
                    AssertEqual("External fallback text", fallbackBindingText.Text, "external SDK binding fallback value text");
                    var fallbackBindingExpression = fallbackBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK fallback BindingExpression.");
                    AssertEqual("MissingExternalBindingText", fallbackBindingExpression.ParentBinding.Path.Path, "external SDK binding fallback path");
                    AssertEqual("External fallback text", fallbackBindingExpression.ParentBinding.FallbackValue, "external SDK binding fallback value metadata");

                    var targetNullBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalTargetNullBindingText"),
                        "external SDK target-null binding text block");
                    AssertEqual("External null text", targetNullBindingText.Text, "external SDK binding target null value text");
                    var targetNullBindingExpression = targetNullBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK target-null BindingExpression.");
                    AssertEqual("ExternalNullBindingText", targetNullBindingExpression.ParentBinding.Path.Path, "external SDK binding target null path");
                    AssertEqual("External null text", targetNullBindingExpression.ParentBinding.TargetNullValue, "external SDK binding target null value metadata");

                    var delayedBindingTextBox = RequireType<TextBox>(
                        window.FindName("ExternalDelayedBindingTextBox"),
                        "external SDK delayed binding text box");
                    AssertEqual("external delayed initial", delayedBindingTextBox.Text, "external SDK delayed binding initial target text");
                    var delayedBindingExpression = delayedBindingTextBox.GetBindingExpression(TextBox.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK delayed BindingExpression.");
                    AssertEqual("ExternalDelayedBindingText", delayedBindingExpression.ParentBinding.Path.Path, "external SDK delayed binding path");
                    AssertEqual(UpdateSourceTrigger.PropertyChanged, delayedBindingExpression.ParentBinding.UpdateSourceTrigger, "external SDK delayed binding update trigger");
                    AssertEqual(25, delayedBindingExpression.ParentBinding.Delay, "external SDK delayed binding delay metadata");
                    delayedBindingTextBox.Text = "external delayed source refresh";
                    AssertEqual("external delayed initial", window.ExternalDelayedBindingText, "external SDK delayed binding immediate source value");
                    System.Threading.Thread.Sleep(75);
                    DrainDispatcher();
                    AssertEqual("external delayed source refresh", window.ExternalDelayedBindingText, "external SDK delayed binding source value");

                    var oneTimeBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalOneTimeBindingText"),
                        "external SDK OneTime binding text block");
                    AssertEqual("external one-time initial", oneTimeBindingText.Text, "external SDK OneTime binding initial target text");
                    var oneTimeBindingExpression = oneTimeBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK OneTime BindingExpression.");
                    AssertEqual("ExternalOneTimeBindingValue", oneTimeBindingExpression.ParentBinding.Path.Path, "external SDK OneTime binding path");
                    AssertEqual(BindingMode.OneTime, oneTimeBindingExpression.ParentBinding.Mode, "external SDK OneTime binding mode");
                    window.ExternalOneTimeBindingValue = "external one-time updated";
                    DrainDispatcher();
                    AssertEqual("external one-time initial", oneTimeBindingText.Text, "external SDK OneTime binding retained target text");

                    var oneWayToSourceBindingTextBox = RequireType<TextBox>(
                        window.FindName("ExternalOneWayToSourceBindingTextBox"),
                        "external SDK OneWayToSource binding text box");
                    var oneWayToSourceBindingExpression = oneWayToSourceBindingTextBox.GetBindingExpression(TextBox.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK OneWayToSource BindingExpression.");
                    AssertEqual("ExternalOneWayToSourceBindingText", oneWayToSourceBindingExpression.ParentBinding.Path.Path, "external SDK OneWayToSource binding path");
                    AssertEqual(BindingMode.OneWayToSource, oneWayToSourceBindingExpression.ParentBinding.Mode, "external SDK OneWayToSource binding mode");
                    AssertEqual(UpdateSourceTrigger.PropertyChanged, oneWayToSourceBindingExpression.ParentBinding.UpdateSourceTrigger, "external SDK OneWayToSource binding update trigger");
                    oneWayToSourceBindingTextBox.Text = "external one-way source refresh";
                    DrainDispatcher();
                    AssertEqual("external one-way source refresh", window.ExternalOneWayToSourceBindingText, "external SDK OneWayToSource binding source value");

                    var indexedBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalIndexedBindingText"),
                        "external SDK indexed binding text block");
                    AssertEqual("Indexed Beta", indexedBindingText.Text, "external SDK indexed binding initial target text");
                    var indexedBindingExpression = indexedBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK indexed BindingExpression.");
                    AssertEqual("ExternalIndexedItems[1].Name", indexedBindingExpression.ParentBinding.Path.Path, "external SDK indexed binding path");
                    window.ExternalIndexedItems[1].Name = "Indexed Beta Updated";
                    DrainDispatcher();
                    AssertEqual("Indexed Beta Updated", indexedBindingText.Text, "external SDK indexed binding updated target text");

                    var stringFormatBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalStringFormatBindingText"),
                        "external SDK StringFormat binding text block");
                    AssertEqual("External formatted Alpha", stringFormatBindingText.Text, "external SDK StringFormat binding target text");
                    var stringFormatBindingExpression = stringFormatBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK StringFormat BindingExpression.");
                    AssertEqual("SelectedExternalItem.Name", stringFormatBindingExpression.ParentBinding.Path.Path, "external SDK StringFormat binding path");
                    AssertEqual("External formatted {0}", stringFormatBindingExpression.ParentBinding.StringFormat, "external SDK StringFormat binding metadata");

                    var transferTextBox = RequireType<TextBox>(
                        window.FindName("ExternalBindingTransferTextBox"),
                        "external SDK binding transfer text box");
                    var transferBindingExpression = transferTextBox.GetBindingExpression(TextBox.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK binding transfer BindingExpression.");
                    AssertEqual("ExternalBindingTransferText", transferBindingExpression.ParentBinding.Path.Path, "external SDK binding transfer path");
                    AssertEqual(BindingMode.TwoWay, transferBindingExpression.ParentBinding.Mode, "external SDK binding transfer mode");
                    AssertEqual(UpdateSourceTrigger.Explicit, transferBindingExpression.ParentBinding.UpdateSourceTrigger, "external SDK binding transfer update source trigger");
                    AssertEqual(true, transferBindingExpression.ParentBinding.NotifyOnSourceUpdated, "external SDK binding transfer NotifyOnSourceUpdated");
                    AssertEqual(true, transferBindingExpression.ParentBinding.NotifyOnTargetUpdated, "external SDK binding transfer NotifyOnTargetUpdated");
                    AssertEqual("external transfer initial", transferTextBox.Text, "external SDK binding transfer initial target value");

                    int targetUpdatedBefore = window.ExternalBindingTargetUpdatedCount;
                    window.ExternalBindingTransferText = "external transfer target refresh";
                    transferBindingExpression.UpdateTarget();
                    DrainDispatcher();
                    AssertEqual("external transfer target refresh", transferTextBox.Text, "external SDK Binding TargetUpdated target value");
                    AssertAtLeast(targetUpdatedBefore + 1, window.ExternalBindingTargetUpdatedCount, "external SDK Binding TargetUpdated routed event");
                    AssertEqual("ExternalBindingTransferTextBox", window.LastExternalBindingTargetUpdatedSenderName, "external SDK Binding TargetUpdated sender");
                    AssertEqual("ExternalBindingTransferTextBox", window.LastExternalBindingTargetUpdatedTargetName, "external SDK Binding TargetUpdated target object");
                    AssertEqual("Text", window.LastExternalBindingTargetUpdatedPropertyName, "external SDK Binding TargetUpdated property");
                    AssertEqual("TargetUpdated", window.LastExternalBindingTargetUpdatedRoutedEventName, "external SDK Binding TargetUpdated routed event name");

                    int sourceUpdatedBefore = window.ExternalBindingSourceUpdatedCount;
                    transferTextBox.Text = "external transfer source refresh";
                    transferBindingExpression.UpdateSource();
                    DrainDispatcher();
                    AssertEqual("external transfer source refresh", window.ExternalBindingTransferText, "external SDK Binding SourceUpdated source value");
                    AssertAtLeast(sourceUpdatedBefore + 1, window.ExternalBindingSourceUpdatedCount, "external SDK Binding SourceUpdated routed event");
                    AssertEqual("ExternalBindingTransferTextBox", window.LastExternalBindingSourceUpdatedSenderName, "external SDK Binding SourceUpdated sender");
                    AssertEqual("ExternalBindingTransferTextBox", window.LastExternalBindingSourceUpdatedTargetName, "external SDK Binding SourceUpdated target object");
                    AssertEqual("Text", window.LastExternalBindingSourceUpdatedPropertyName, "external SDK Binding SourceUpdated property");
                    AssertEqual("SourceUpdated", window.LastExternalBindingSourceUpdatedRoutedEventName, "external SDK Binding SourceUpdated routed event name");

                    var selfBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalSelfBindingText"),
                        "external SDK self binding text block");
                    DrainDispatcher();
                    AssertEqual("External self tag", selfBindingText.Text, "external SDK RelativeSource self binding value");
                    var selfBindingExpression = selfBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK RelativeSource Self BindingExpression.");
                    AssertEqual("Tag", selfBindingExpression.ParentBinding.Path.Path, "external SDK RelativeSource self binding path");
                    var selfRelativeSource = selfBindingExpression.ParentBinding.RelativeSource
                        ?? throw new InvalidOperationException("Expected external SDK RelativeSource Self binding metadata.");
                    AssertEqual(RelativeSourceMode.Self, selfRelativeSource.Mode, "external SDK RelativeSource self mode");

                    var ancestorBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalAncestorBindingText"),
                        "external SDK ancestor binding text block");
                    AssertEqual("External ancestor tag", ancestorBindingText.Text, "external SDK RelativeSource ancestor binding value");
                    var ancestorBindingExpression = ancestorBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK RelativeSource ancestor BindingExpression.");
                    AssertEqual("Tag", ancestorBindingExpression.ParentBinding.Path.Path, "external SDK RelativeSource ancestor binding path");
                    var ancestorRelativeSource = ancestorBindingExpression.ParentBinding.RelativeSource
                        ?? throw new InvalidOperationException("Expected external SDK RelativeSource ancestor binding metadata.");
                    AssertEqual(RelativeSourceMode.FindAncestor, ancestorRelativeSource.Mode, "external SDK RelativeSource ancestor mode");
                    AssertEqual(typeof(Border), ancestorRelativeSource.AncestorType, "external SDK RelativeSource ancestor type");
                    AssertEqual(1, ancestorRelativeSource.AncestorLevel, "external SDK RelativeSource ancestor level");

                    var ancestorLevelBindingText = RequireType<TextBlock>(
                        window.FindName("ExternalAncestorLevelBindingText"),
                        "external SDK ancestor-level binding text block");
                    AssertEqual("External second ancestor tag", ancestorLevelBindingText.Text, "external SDK RelativeSource ancestor-level binding value");
                    var ancestorLevelBindingExpression = ancestorLevelBindingText.GetBindingExpression(TextBlock.TextProperty)
                        ?? throw new InvalidOperationException("Expected external SDK RelativeSource ancestor-level BindingExpression.");
                    AssertEqual("Tag", ancestorLevelBindingExpression.ParentBinding.Path.Path, "external SDK RelativeSource ancestor-level binding path");
