                private static void ValidateAutomationPatternProviders(
                    MainWindow window,
                    Button commandButton,
                    TextBox validationTextBox)
                {
                    var commandButtonPeer = RequireType<ButtonAutomationPeer>(
                        UIElementAutomationPeer.CreatePeerForElement(commandButton),
                        "external SDK command button automation peer");
                    var invokeProvider = RequireType<IInvokeProvider>(
                        commandButtonPeer.GetPattern(PatternInterface.Invoke),
                        "external SDK command button invoke provider");
                    int automationClickBefore = window.ExternalCommandButtonClickCount;
                    int automationExecutedBefore = window.ExternalCommandExecutedCount;
                    invokeProvider.Invoke();
                    DrainDispatcher();
                    AssertEqual(automationClickBefore + 1, window.ExternalCommandButtonClickCount, "external SDK automation invoke click count");
                    AssertEqual(automationExecutedBefore + 1, window.ExternalCommandExecutedCount, "external SDK automation invoke command count");
                    AssertEqual("ExternalCommandParameter", window.LastExternalCommandParameter, "external SDK automation invoke command parameter");

                    var validationPeer = RequireType<TextBoxAutomationPeer>(
                        UIElementAutomationPeer.CreatePeerForElement(validationTextBox),
                        "external SDK text box automation peer for value pattern");
                    var valueProvider = RequireType<IValueProvider>(
                        validationPeer.GetPattern(PatternInterface.Value),
                        "external SDK text box value provider");
                    AssertEqual(false, valueProvider.IsReadOnly, "external SDK automation value provider read-only state");
                    valueProvider.SetValue("external automation value");
                    AssertEqual("external automation value", valueProvider.Value, "external SDK automation value provider value");
                    AssertEqual("external automation value", validationTextBox.Text, "external SDK automation value provider text box text");

                    var checkBox = RequireType<CheckBox>(
                        window.FindName("ExternalCheckBox"),
                        "external SDK check box for automation peer");
                    checkBox.IsChecked = false;
                    DrainDispatcher();
                    var checkBoxPeer = RequireType<CheckBoxAutomationPeer>(
                        UIElementAutomationPeer.CreatePeerForElement(checkBox),
                        "external SDK check box automation peer");
                    var toggleProvider = RequireType<IToggleProvider>(
                        checkBoxPeer.GetPattern(PatternInterface.Toggle),
                        "external SDK check box toggle provider");
                    AssertEqual(ToggleState.Off, toggleProvider.ToggleState, "external SDK automation toggle initial state");
                    int automationCheckedBefore = window.ExternalCheckBoxCheckedCount;
                    toggleProvider.Toggle();
                    DrainDispatcher();
                    AssertEqual(ToggleState.On, toggleProvider.ToggleState, "external SDK automation toggle on state");
                    AssertEqual(true, checkBox.IsChecked == true, "external SDK automation toggle check box state");
                    AssertAtLeast(automationCheckedBefore + 1, window.ExternalCheckBoxCheckedCount, "external SDK automation toggle checked count");
                    int automationUncheckedBefore = window.ExternalCheckBoxUncheckedCount;
                    toggleProvider.Toggle();
                    DrainDispatcher();
                    AssertEqual(ToggleState.Off, toggleProvider.ToggleState, "external SDK automation toggle restored state");
                    AssertEqual(false, checkBox.IsChecked == true, "external SDK automation toggle check box restored state");
                    AssertAtLeast(automationUncheckedBefore + 1, window.ExternalCheckBoxUncheckedCount, "external SDK automation toggle unchecked count");

                    var slider = RequireType<Slider>(
                        window.FindName("ExternalSlider"),
                        "external SDK slider for automation peer");
                    var progressBar = RequireType<ProgressBar>(
                        window.FindName("ExternalProgressBar"),
                        "external SDK progress bar for automation peer");
                    var sliderPeer = RequireType<SliderAutomationPeer>(
                        UIElementAutomationPeer.CreatePeerForElement(slider),
                        "external SDK slider automation peer");
                    var rangeProvider = RequireType<IRangeValueProvider>(
                        sliderPeer.GetPattern(PatternInterface.RangeValue),
                        "external SDK slider range provider");
                    AssertEqual(false, rangeProvider.IsReadOnly, "external SDK automation range read-only state");
                    AssertEqual(0.0, rangeProvider.Minimum, "external SDK automation range minimum");
                    AssertEqual(100.0, rangeProvider.Maximum, "external SDK automation range maximum");
                    AssertEqual(2.0, rangeProvider.SmallChange, "external SDK automation range small change");
                    AssertEqual(10.0, rangeProvider.LargeChange, "external SDK automation range large change");
                    int automationSliderChangedBefore = window.ExternalSliderValueChangedCount;
                    rangeProvider.SetValue(55.0);
                    DrainDispatcher();
                    AssertClose(55.0, rangeProvider.Value, "external SDK automation range value");
                    AssertClose(55.0, slider.Value, "external SDK automation range slider value");
                    AssertClose(55.0, progressBar.Value, "external SDK automation range progress value");
                    AssertClose(55.0, window.LastExternalSliderValue, "external SDK automation range event value");
                    AssertAtLeast(automationSliderChangedBefore + 1, window.ExternalSliderValueChangedCount, "external SDK automation range changed count");
                }

                private static void ValidateSystemCommandButton(
                    MainWindow window,
                    Button button,
                    RoutedCommand expectedCommand,
                    string expectedParameter,
                    WindowState expectedState,
                    string description)
                {
                    DrainDispatcher();
                    AssertEqual(expectedCommand, button.Command, $"{description} command binding");
                    AssertEqual(expectedParameter, button.CommandParameter, $"{description} command parameter");
                    AssertEqual(window, button.CommandTarget, $"{description} command target");

                    int canExecuteBefore = window.ExternalSystemCommandCanExecuteCount;
                    int executedBefore = window.ExternalSystemCommandExecutedCount;
                    AssertEqual(true, expectedCommand.CanExecute(button.CommandParameter, window), $"{description} can execute");
                    expectedCommand.Execute(button.CommandParameter, window);

                    AssertAtLeast(canExecuteBefore + 1, window.ExternalSystemCommandCanExecuteCount, $"{description} can-execute count");
                    AssertEqual(executedBefore + 1, window.ExternalSystemCommandExecutedCount, $"{description} executed count");
                    AssertEqual(expectedCommand.Name, window.LastExternalSystemCommandName, $"{description} command name");
                    AssertEqual(expectedParameter, window.LastExternalSystemCommandParameter, $"{description} executed parameter");
                    AssertEqual(expectedState, window.WindowState, $"{description} window state");
                }

                private static void ValidateAccessKeyRoutingAfterRun(MainWindow window)
                {
                    var validationTextBox = RequireType<TextBox>(
                        window.FindName("ExternalValidationTextBox"),
                        "external SDK access-key routing target text box");
                    var presentationSource = PresentationSource.FromVisual(window)
                        ?? throw new InvalidOperationException("Expected external SDK window to have a presentation source.");

                    AssertEqual(true, AccessKeyManager.IsKeyRegistered(presentationSource, "E"), "external SDK access-key manager registered label key");
                    Keyboard.ClearFocus();
                    AssertEqual(false, ReferenceEquals(validationTextBox, Keyboard.FocusedElement), "external SDK access-key manager cleared focus");
                    AssertEqual(false, AccessKeyManager.ProcessKey(presentationSource, "E", false), "external SDK access-key manager process last key");
                    AssertEqual(validationTextBox, Keyboard.FocusedElement, "external SDK access-key manager focused label target");
                    Keyboard.ClearFocus();
                }

                private static void ValidateClassInputBindingAfterRun(MainWindow window)
                {
                    var classCommandTarget = RequireType<ExternalClassCommandTextBox>(
                        window.FindName("ExternalClassCommandTarget"),
                        "external SDK class input binding runtime target");

                    Keyboard.Focus(classCommandTarget);
                    AssertEqual(classCommandTarget, Keyboard.FocusedElement, "external SDK class input binding focused target");
                    int classExecutedBefore = classCommandTarget.ClassCommandExecutedCount;
                    object keyDown = CreatePortableInputEvent("KeyDown", key: "F8", modifiersName: "Control");
                    HandlePortableInput(window, keyDown);

                    AssertEqual(true, GetPropertyValue<bool>(keyDown, "Handled"), "external SDK class input binding key event handled");
                    AssertEqual(classExecutedBefore + 1, classCommandTarget.ClassCommandExecutedCount, "external SDK class input binding command execution count");
                    AssertEqual("ExternalClassInputParameter", classCommandTarget.LastClassCommandParameter, "external SDK class input binding command parameter");
                    AssertEqual(nameof(ExternalClassCommandTextBox.ExternalClassCommand), classCommandTarget.LastClassCommandName, "external SDK class input binding command name");

                    object keyUp = CreatePortableInputEvent("KeyUp", key: "F8", modifiersName: "None");
                    HandlePortableInput(window, keyUp);
                    AssertEqual(
                        classExecutedBefore + 1,
                        classCommandTarget.ClassCommandExecutedCount,
                        "external SDK class input binding ignores key up");
                    Keyboard.ClearFocus();
                }

                private static void ValidateThumbDragManager(MainWindow window)
                {
                    var focusPanel = RequireType<StackPanel>(
                        window.FindName("ExternalFocusPanel"),
                        "external SDK Thumb drag parent panel");
                    var thumb = RequireType<Thumb>(
                        window.FindName("ExternalDragThumb"),
                        "external SDK Thumb drag manager");
                    AssertEqual(24.0, thumb.Width, "external SDK Thumb width");
                    AssertEqual(18.0, thumb.Height, "external SDK Thumb height");
                    AssertEqual("external drag thumb", thumb.Tag, "external SDK Thumb tag");
                    AssertEqual(false, thumb.Focusable, "external SDK Thumb focusable metadata");
                    AssertEqual(false, thumb.IsDragging, "external SDK Thumb initial dragging state");
                    AssertEqual(0, window.ExternalThumbDragStartedCount, "external SDK Thumb initial DragStarted count");
                    AssertEqual(0, window.ExternalThumbDragDeltaCount, "external SDK Thumb initial DragDelta count");
                    AssertEqual(0, window.ExternalThumbDragCompletedCount, "external SDK Thumb initial DragCompleted count");
                    AssertEqual(0, window.ExternalBubbledThumbDragDeltaCount, "external SDK Thumb initial bubbled DragDelta count");

                    var started = new DragStartedEventArgs(2.5, 3.5)
                    {
                        RoutedEvent = Thumb.DragStartedEvent
                    };
                    var delta = new DragDeltaEventArgs(4.0, 6.0)
                    {
                        RoutedEvent = Thumb.DragDeltaEvent
                    };
                    var completed = new DragCompletedEventArgs(8.0, 10.0, true)
                    {
                        RoutedEvent = Thumb.DragCompletedEvent
                    };

                    thumb.RaiseEvent(started);
                    thumb.RaiseEvent(delta);
                    thumb.RaiseEvent(completed);

                    AssertEqual(1, window.ExternalThumbDragStartedCount, "external SDK Thumb DragStarted handler count");
                    AssertEqual("ExternalDragThumb", window.LastExternalThumbDragStartedSenderName, "external SDK Thumb DragStarted sender");
                    AssertEqual("DragStarted", window.LastExternalThumbDragStartedRoutedEventName, "external SDK Thumb DragStarted routed event");
                    AssertEqual(2.5, window.LastExternalThumbDragStartedHorizontalOffset, "external SDK Thumb DragStarted horizontal offset");
                    AssertEqual(3.5, window.LastExternalThumbDragStartedVerticalOffset, "external SDK Thumb DragStarted vertical offset");

                    AssertEqual(1, window.ExternalThumbDragDeltaCount, "external SDK Thumb DragDelta handler count");
                    AssertEqual("ExternalDragThumb", window.LastExternalThumbDragDeltaSenderName, "external SDK Thumb DragDelta sender");
                    AssertEqual("DragDelta", window.LastExternalThumbDragDeltaRoutedEventName, "external SDK Thumb DragDelta routed event");
                    AssertEqual(4.0, window.LastExternalThumbDragDeltaHorizontalChange, "external SDK Thumb DragDelta horizontal change");
                    AssertEqual(6.0, window.LastExternalThumbDragDeltaVerticalChange, "external SDK Thumb DragDelta vertical change");
                    AssertEqual(1, window.ExternalBubbledThumbDragDeltaCount, "external SDK Thumb bubbled DragDelta handler count");
                    AssertEqual("ExternalFocusPanel", window.LastExternalBubbledThumbDragDeltaSenderName, "external SDK Thumb bubbled DragDelta sender");
                    AssertEqual("ExternalDragThumb", window.LastExternalBubbledThumbDragDeltaOriginalSourceName, "external SDK Thumb bubbled DragDelta original source");
                    AssertEqual("DragDelta", window.LastExternalBubbledThumbDragDeltaRoutedEventName, "external SDK Thumb bubbled DragDelta routed event");
                    AssertEqual(4.0, window.LastExternalBubbledThumbDragDeltaHorizontalChange, "external SDK Thumb bubbled DragDelta horizontal change");
                    AssertEqual(6.0, window.LastExternalBubbledThumbDragDeltaVerticalChange, "external SDK Thumb bubbled DragDelta vertical change");

                    AssertEqual(1, window.ExternalThumbDragCompletedCount, "external SDK Thumb DragCompleted handler count");
                    AssertEqual("ExternalDragThumb", window.LastExternalThumbDragCompletedSenderName, "external SDK Thumb DragCompleted sender");
                    AssertEqual("DragCompleted", window.LastExternalThumbDragCompletedRoutedEventName, "external SDK Thumb DragCompleted routed event");
                    AssertEqual(8.0, window.LastExternalThumbDragCompletedHorizontalChange, "external SDK Thumb DragCompleted horizontal change");
                    AssertEqual(10.0, window.LastExternalThumbDragCompletedVerticalChange, "external SDK Thumb DragCompleted vertical change");
                    AssertEqual(true, window.LastExternalThumbDragCompletedCanceled, "external SDK Thumb DragCompleted canceled state");
                    AssertEqual(true, ReferenceEquals(focusPanel, thumb.Parent), "external SDK Thumb logical parent");
                }

                private static object CreatePortableInputEvent(
                    string kindName,
                    string? key = null,
                    int scanCode = 0,
                    string modifiersName = "None",
                    char? character = null,
                    double x = 0,
                    double y = 0,
                    double deltaX = 0,
                    double deltaY = 0,
                    string buttonName = "None")
                {
                    Assembly presentationFramework = typeof(Window).Assembly;
                    Type argsType = RequireType<Type>(
                        presentationFramework.GetType("System.Windows.PortableInputEventArgs", throwOnError: true),
                        "portable input event args type");
                    Type kindType = RequireType<Type>(
                        presentationFramework.GetType("System.Windows.PortableInputEventKind", throwOnError: true),
                        "portable input event kind type");
                    Type buttonType = RequireType<Type>(
                        presentationFramework.GetType("System.Windows.PortableMouseButton", throwOnError: true),
                        "portable mouse button type");
                    Type modifiersType = RequireType<Type>(
                        presentationFramework.GetType("System.Windows.PortableInputModifiers", throwOnError: true),
                        "portable input modifiers type");

                    return Activator.CreateInstance(
                        argsType,
                        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                        binder: null,
                        args: new object?[]
                        {
                            Enum.Parse(kindType, kindName),
                            key,
                            scanCode,
                            character,
                            x,
                            y,
                            deltaX,
                            deltaY,
                            Enum.Parse(buttonType, buttonName),
                            Enum.Parse(modifiersType, modifiersName)
                        },
                        culture: null)
                        ?? throw new InvalidOperationException($"Failed to create '{argsType.FullName}'.");
                }

                private static void HandlePortableInput(Window window, object input)
                {
                    MethodInfo handlePortableInput = typeof(Window).GetMethod(
                        "HandlePortableInput",
                        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? throw new MissingMethodException(typeof(Window).FullName, "HandlePortableInput");

                    handlePortableInput.Invoke(window, [input]);
                }

                private static T GetPropertyValue<T>(object instance, string propertyName)
                {
                    PropertyInfo property = instance.GetType().GetProperty(
                        propertyName,
                        BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? throw new MissingMemberException(instance.GetType().FullName, propertyName);
                    object? value = property.GetValue(instance);
                    return value is T typed
                        ? typed
                        : throw new InvalidOperationException(
                            $"Expected '{instance.GetType().FullName}.{propertyName}' to be {typeof(T).FullName}, but found {value?.GetType().FullName ?? "<null>"}.");
                }

                private static void ValidateKeyboardNavigationAfterRun(MainWindow window)
                {
                    var keyboardNavigationPanel = RequireType<StackPanel>(
                        window.FindName("ExternalKeyboardNavigationPanel"),
                        "external SDK keyboard navigation runtime panel");
                    var firstButton = RequireType<Button>(
                        window.FindName("ExternalKeyboardNavigationFirstButton"),
                        "external SDK first keyboard navigation runtime button");
                    var secondButton = RequireType<Button>(
                        window.FindName("ExternalKeyboardNavigationSecondButton"),
                        "external SDK second keyboard navigation runtime button");

                    keyboardNavigationPanel.UpdateLayout();
                    AssertEqual(firstButton, Keyboard.Focus(firstButton), "external SDK KeyboardNavigation initial focus");
                    AssertEqual(firstButton, Keyboard.FocusedElement, "external SDK KeyboardNavigation focused first button");
                    AssertEqual(true, firstButton.MoveFocus(new TraversalRequest(FocusNavigationDirection.Next)), "external SDK KeyboardNavigation next move result");
                    AssertEqual(secondButton, Keyboard.FocusedElement, "external SDK KeyboardNavigation focused second button");
                    AssertEqual(true, secondButton.MoveFocus(new TraversalRequest(FocusNavigationDirection.Next)), "external SDK KeyboardNavigation cycle next move result");
                    AssertEqual(firstButton, Keyboard.FocusedElement, "external SDK KeyboardNavigation cycled first button");
                    AssertEqual(true, firstButton.MoveFocus(new TraversalRequest(FocusNavigationDirection.Previous)), "external SDK KeyboardNavigation previous move result");
                    AssertEqual(secondButton, Keyboard.FocusedElement, "external SDK KeyboardNavigation cycled previous button");
                    Keyboard.ClearFocus();
                }

                private static void DrainDispatcher()
                {
                    bool markerReached = false;
                    var frame = new DispatcherFrame();
                    var markerOperation = Dispatcher.CurrentDispatcher.BeginInvoke(
                        DispatcherPriority.ApplicationIdle,
                        new Action(() =>
                        {
                            markerReached = true;
                            frame.Continue = false;
                        }));
                    var timer = new DispatcherTimer(DispatcherPriority.Send)
                    {
                        Interval = TimeSpan.FromMilliseconds(250)
                    };
                    timer.Tick += (_, _) =>
                    {
                        timer.Stop();
                        frame.Continue = false;
                    };
                    timer.Start();
                    Dispatcher.PushFrame(frame);
                    timer.Stop();
                    if (!markerReached && markerOperation.Status == DispatcherOperationStatus.Pending)
                    {
                        markerOperation.Abort();
                    }
                }

                private static void PumpDispatcherUntil(Func<bool> condition, TimeSpan timeout, string description)
                {
                    var deadline = DateTime.UtcNow + timeout;
                    while (!condition())
                    {
                        DrainDispatcher();

                        if (condition())
                        {
                            return;
                        }

                        if (DateTime.UtcNow >= deadline)
                        {
                            throw new InvalidOperationException($"Timed out waiting for {description}.");
                        }

                        Thread.Sleep(1);
                    }
                }

                private static T RequireFirstInline<T>(InlineCollection inlines, string description)
                    where T : Inline
                {
                    foreach (Inline inline in inlines)
                    {
                        if (inline is T typed)
                        {
                            return typed;
                        }
                    }

                    throw new InvalidOperationException(
                        $"Expected {description} to contain {typeof(T).FullName}.");
                }

                private static T RequireFirstInlineExact<T>(InlineCollection inlines, string description)
                    where T : Inline
                {
                    foreach (Inline inline in inlines)
                    {
                        if (inline.GetType() == typeof(T))
                        {
                            return (T)inline;
                        }
                    }

                    throw new InvalidOperationException(
                        $"Expected {description} to contain exact {typeof(T).FullName}.");
                }

                private static T RequireType<T>(object? value, string description)
                {
                    if (value is T typed)
                    {
                        return typed;
                    }

                    throw new InvalidOperationException(
                        $"Expected {description} to be {typeof(T).FullName}, but found {value?.GetType().FullName ?? "<null>"}.");
                }

                private static FrameworkElement? FindVisualDescendantByName(DependencyObject root, string name)
                {
                    int childCount = VisualTreeHelper.GetChildrenCount(root);
                    for (int i = 0; i < childCount; i++)
                    {
                        DependencyObject child = VisualTreeHelper.GetChild(root, i);
                        if (child is FrameworkElement element &&
                            string.Equals(element.Name, name, StringComparison.Ordinal))
                        {
                            return element;
                        }

                        FrameworkElement? nested = FindVisualDescendantByName(child, name);
                        if (nested is not null)
                        {
                            return nested;
                        }
                    }

                    return null;
                }

                private static bool ContainsGroup(System.Collections.IEnumerable groups, string name)
                {
                    foreach (object group in groups)
                    {
                        if (group is CollectionViewGroup collectionViewGroup
                            && string.Equals(collectionViewGroup.Name?.ToString(), name, StringComparison.Ordinal))
                        {
                            return true;
                        }
                    }

                    return false;
                }

                private static int GetGroupItemCount(System.Collections.IEnumerable groups, string name)
                {
                    foreach (object group in groups)
                    {
                        if (group is CollectionViewGroup collectionViewGroup
                            && string.Equals(collectionViewGroup.Name?.ToString(), name, StringComparison.Ordinal))
                        {
                            return collectionViewGroup.ItemCount;
                        }
                    }

                    return 0;
                }

                private static void AssertBrushColor(Brush brush, string expected, string description)
                {
                    var solidColorBrush = RequireType<SolidColorBrush>(brush, description);
                    AssertEqual(expected, solidColorBrush.Color.ToString(), description);
                }

                private static void AssertTemplateText(DataTemplate template, object dataContext, string expectedText, string description)
                {
                    var text = RequireType<TextBlock>(
                        template.LoadContent(),
                        description + " root");
                    text.DataContext = dataContext;
                    DrainDispatcher();
                    AssertEqual(expectedText, text.Text, description);
                }

                private static void AssertParagraphText(Paragraph paragraph, string expectedText, string description)
                {
                    var run = RequireFirstInline<Run>(
                        paragraph.Inlines,
                        $"external SDK FlowDocument {description} run");
                    AssertEqual(expectedText, run.Text, $"external SDK FlowDocument {description} text");
                }

                private static void AssertListItemText(ListItem? listItem, string expectedText, string description)
                {
                    var item = RequireType<ListItem>(
                        listItem,
                        $"external SDK FlowDocument {description} list item");
                    var paragraph = RequireType<Paragraph>(
                        item.Blocks.FirstBlock,
                        $"external SDK FlowDocument {description} list item paragraph");
                    AssertParagraphText(paragraph, expectedText, $"{description} list item");
                }

                private static void AssertTableCellText(TableCell tableCell, string expectedText, string description)
                {
                    var paragraph = RequireType<Paragraph>(
                        tableCell.Blocks.FirstBlock,
                        $"external SDK FlowDocument {description} table cell paragraph");
                    AssertParagraphText(paragraph, expectedText, $"{description} table cell");
                }

                private static Setter AssertLooseStyleSetter(
                    SetterBase setterBase,
                    DependencyProperty expectedProperty,
                    object expectedValue,
                    string description)
                {
                    var setter = RequireType<Setter>(
                        setterBase,
                        description);
                    AssertEqual(expectedProperty, setter.Property, $"{description} property");
                    AssertEqual(expectedValue, setter.Value, $"{description} value");
                    return setter;
                }

                private static void AssertEqual<T>(T expected, T actual, string description)
                {
                    if (!EqualityComparer<T>.Default.Equals(expected, actual))
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to be '{expected}', but found '{actual}'.");
                    }
                }

                private static void AssertClose(double expected, double actual, string description)
                {
                    AssertClose(expected, actual, 0.000001, description);
                }

                private static void AssertClose(double expected, double actual, double tolerance, string description)
                {
                    if (Math.Abs(expected - actual) > tolerance)
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to be close to '{expected}', but found '{actual}'.");
                    }
                }

                private static void AssertBetween(double minimum, double maximum, double actual, string description)
                {
                    if (actual < minimum || actual > maximum)
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to be between '{minimum}' and '{maximum}', but found '{actual}'.");
                    }
                }

                private static void AssertContains(string expectedSubstring, string actual, string description)
                {
                    if (!actual.Contains(expectedSubstring, StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to contain '{expectedSubstring}', but found '{actual}'.");
                    }
                }

                private static void AssertAtLeast(int expectedMinimum, int actual, string description)
                {
                    if (actual < expectedMinimum)
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to be at least '{expectedMinimum}', but found '{actual}'.");
                    }
                }

                private static void AssertEndsWith(string? value, string expectedSuffix, string description)
                {
                    if (value is null || !value.EndsWith(expectedSuffix, StringComparison.Ordinal))
                    {
                        throw new InvalidOperationException(
                            $"Expected {description} to end with '{expectedSuffix}', but found '{value ?? "<null>"}'.");
                    }
                }
            }
            """);

        return appProjectPath;
    }

    private static string PrepareExternalCentralPackageManagementApp(string workRoot, string packageFeed)
    {
        if (Directory.Exists(workRoot))
        {
            Directory.Delete(workRoot, recursive: true);
        }

        string appRoot = Path.Combine(workRoot, CentralPackageManagementAssemblyName);
        Directory.CreateDirectory(appRoot);

        WriteFile(
            Path.Combine(workRoot, "NuGet.config"),
            $"""
            <?xml version="1.0" encoding="utf-8"?>
            <configuration>
              <config>
                <add key="globalPackagesFolder" value="{SecurityElement.Escape(Path.Combine(workRoot, ".packages"))}" />
              </config>
              <packageSources>
                <clear />
                <add key="ProGPUWpfLocalArtifacts" value="{SecurityElement.Escape(packageFeed)}" />
                <add key="nuget.org" value="https://api.nuget.org/v3/index.json" />
              </packageSources>
            </configuration>
            """);

        WriteFile(
            Path.Combine(workRoot, "Directory.Packages.props"),
            """
            <Project>
              <PropertyGroup>
                <ManagePackageVersionsCentrally>true</ManagePackageVersionsCentrally>
              </PropertyGroup>

              <ItemGroup>
                <PackageVersion Include="System.Reactive" Version="6.0.1" />
              </ItemGroup>
            </Project>
            """);

        string projectPath = Path.Combine(appRoot, CentralPackageManagementAssemblyName + ".csproj");
        WriteFile(
            projectPath,
            SwitchWpfSdkOnly(
                $"""
            <Project Sdk="{OriginalWpfSdk}">
              <PropertyGroup>
                <OutputType>WinExe</OutputType>
                <AssemblyName>{CentralPackageManagementOutputAssemblyName}</AssemblyName>
                <TargetFramework>{ExternalAppTargetFramework}</TargetFramework>
                <UseWPF>true</UseWPF>
              </PropertyGroup>

              <ItemGroup>
                <PackageReference Include="System.Reactive" />
              </ItemGroup>
            </Project>
            """,
                "external SDK central package management app"));

        WriteFile(
            Path.Combine(appRoot, "App.xaml"),
            """
            <Application
                x:Class="ExternalCpmSdkApp.App"
                xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
                StartupUri="MainWindow.xaml" />
            """);

        WriteFile(
            Path.Combine(appRoot, "App.xaml.cs"),
            """
            using System.Windows;

            namespace ExternalCpmSdkApp;

            public partial class App : Application
            {
            }
            """);

        WriteFile(
            Path.Combine(appRoot, "MainWindow.xaml"),
            """
            <Window
                x:Class="ExternalCpmSdkApp.MainWindow"
                xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
                Title="External CPM SDK app"
                Width="320"
                Height="180">
                <Grid>
                    <TextBlock
                        HorizontalAlignment="Center"
                        VerticalAlignment="Center"
                        Text="Central Package Management" />
                </Grid>
            </Window>
            """);

        WriteFile(
            Path.Combine(appRoot, "MainWindow.xaml.cs"),
            """
            using System.Windows;

            namespace ExternalCpmSdkApp;

            public partial class MainWindow : Window
            {
                public MainWindow()
                {
                    InitializeComponent();
                }
            }
            """);

        return projectPath;
    }

