                        <TextBlock
                            x:Name="DefaultItemsAncestorBindingText"
                            Text="{Binding Tag, RelativeSource={RelativeSource AncestorType={x:Type Border}}, StringFormat=Ancestor: {0}}" />
                    </Border>
                    <TextBlock
                        x:Name="DefaultItemsTriggeredStatusText"
                        Style="{StaticResource DefaultItemsStatusTriggerStyle}"
                        Text="{Binding Status}" />
                    <TextBlock
                        x:Name="DefaultItemsPropertyTriggeredText"
                        Style="{StaticResource DefaultItemsPropertyTriggerStyle}"
                        Text="Default item property trigger text" />
                    <TextBlock
                        x:Name="DefaultItemsBasedOnText"
                        Style="{StaticResource DefaultItemsBasedOnTextStyle}" />
                    <Button
                        x:Name="DefaultItemsTemplatedButton"
                        Content="Default item templated button"
                        Style="{StaticResource DefaultItemsTemplatedButtonStyle}" />
                    <ListBox
                        x:Name="DefaultItemsListBox"
                        DisplayMemberPath="Name"
                        ItemContainerStyle="{StaticResource DefaultItemsListBoxItemStyle}"
                        ItemsPanel="{StaticResource DefaultItemsListBoxItemsPanel}"
                        ItemsSource="{Binding Items}" />
                    <ListBox
                        x:Name="DefaultItemsSortedListBox"
                        DisplayMemberPath="Name"
                        IsSynchronizedWithCurrentItem="True"
                        ItemsSource="{Binding Source={StaticResource DefaultItemsSortedItems}}" />
                    <ListView
                        x:Name="DefaultItemsListView"
                        ItemsSource="{Binding Items}"
                        SelectedIndex="0">
                        <ListView.View>
                            <GridView>
                                <GridViewColumn
                                    Header="Name"
                                    DisplayMemberBinding="{Binding Name}" />
                                <GridViewColumn
                                    Header="Kind"
                                    DisplayMemberBinding="{Binding Kind}" />
                            </GridView>
                        </ListView.View>
                    </ListView>
                    <DataGrid
                        x:Name="DefaultItemsDataGrid"
                        AutoGenerateColumns="False"
                        CanUserAddRows="False"
                        ItemsSource="{Binding Items}"
                        SelectedItem="{Binding SelectedItem, Mode=TwoWay}">
                        <DataGrid.Columns>
                            <DataGridTextColumn
                                Header="Name"
                                Binding="{Binding Name}" />
                            <DataGridTextColumn
                                Header="Kind"
                                Binding="{Binding Kind}" />
                            <DataGridCheckBoxColumn
                                Header="Active"
                                Binding="{Binding IsActive}" />
                        </DataGrid.Columns>
                    </DataGrid>
                    <DataGrid
                        x:Name="DefaultItemsLargeDataGrid"
                        Height="180"
                        AutoGenerateColumns="False"
                        CanUserAddRows="False"
                        EnableColumnVirtualization="True"
                        EnableRowVirtualization="True"
                        ItemsSource="{Binding LargeItems}"
                        SelectedItem="{Binding SelectedLargeItem, Mode=TwoWay}"
                        ScrollViewer.CanContentScroll="True"
                        ScrollViewer.HorizontalScrollBarVisibility="Auto"
                        ScrollViewer.VerticalScrollBarVisibility="Auto"
                        VirtualizingPanel.IsVirtualizing="True"
                        VirtualizingPanel.ScrollUnit="Pixel"
                        VirtualizingPanel.VirtualizationMode="Recycling">
                        <DataGrid.Columns>
                            <DataGridTextColumn
                                Header="Index"
                                Width="80"
                                Binding="{Binding Index}" />
                            <DataGridTextColumn
                                Header="Name"
                                Width="160"
                                Binding="{Binding Name}" />
                            <DataGridTextColumn
                                Header="Kind"
                                Width="140"
                                Binding="{Binding Kind}" />
                            <DataGridCheckBoxColumn
                                Header="Active"
                                Width="80"
                                Binding="{Binding IsActive}" />
                        </DataGrid.Columns>
                    </DataGrid>
                    <ListBox
                        x:Name="DefaultItemsGroupedListBox"
                        DisplayMemberPath="Name"
                        ItemsSource="{Binding Source={StaticResource DefaultItemsGroupedItems}}">
                        <ListBox.GroupStyle>
                            <GroupStyle HeaderTemplate="{StaticResource DefaultItemsGroupHeaderTemplate}" />
                        </ListBox.GroupStyle>
                    </ListBox>
                    <ListBox x:Name="DefaultItemsCompositeListBox">
                        <ListBox.ItemsSource>
                            <CompositeCollection>
                                <sys:String>Default item composite header</sys:String>
                                <CollectionContainer Collection="{x:Static local:DefaultItemsCompositeProvider.Items}" />
                                <ListBoxItem Content="Default item composite inline container" />
                            </CompositeCollection>
                        </ListBox.ItemsSource>
                    </ListBox>
                    <TreeView
                        x:Name="DefaultItemsTreeView"
                        ItemTemplate="{StaticResource DefaultItemsNodeTemplate}"
                        ItemsSource="{Binding Nodes}" />
                    <ComboBox
                        x:Name="DefaultItemsComboBox"
                        DisplayMemberPath="Name"
                        ItemsSource="{Binding Items}"
                        SelectedItem="{Binding SelectedItem, Mode=TwoWay}" />
                    <TextBlock
                        x:Name="DefaultItemsConvertedSelectionText"
                        Text="{Binding SelectedItem, Converter={StaticResource DefaultItemsItemNameConverter}}" />
                    <ContentControl
                        x:Name="DefaultItemsSelectedTemplateControl"
                        Content="{Binding SelectedItem}"
                        ContentTemplateSelector="{StaticResource DefaultItemsNameTemplateSelector}" />
                    <TextBlock x:Name="DefaultItemsMultiBindingText">
                        <TextBlock.Text>
                            <MultiBinding Converter="{StaticResource DefaultItemsStatusSelectionConverter}">
                                <Binding Path="Status" />
                                <Binding Path="SelectedItem.Name" />
                            </MultiBinding>
                        </TextBlock.Text>
                    </TextBlock>
                    <Button
                        x:Name="DefaultItemsCommandButton"
                        Command="{x:Static local:MainWindow.DefaultItemsCommand}"
                        CommandParameter="button-command"
                        Content="Default item command" />
                    <Button
                        x:Name="DefaultItemsEventSetterButton"
                        Content="Default item event setter"
                        Style="{StaticResource DefaultItemsEventSetterButtonStyle}" />
                    <Button
                        x:Name="DefaultItemsButton"
                        Click="OnDefaultItemsButtonClick"
                        Content="Default item button" />
                </StackPanel>
            </Window>
            """);

        WriteFile(
            Path.Combine(appRoot, "MainWindow.xaml.cs"),
            """
            using System;
            using System.Collections.Generic;
            using System.Collections.ObjectModel;
            using System.Collections.Specialized;
            using System.Configuration;
            using System.ComponentModel;
            using System.Globalization;
            using System.IO;
            using System.Linq;
            using System.Reflection;
            using System.Runtime.CompilerServices;
            using System.Threading.Tasks;
            using ExternalSdkDefaultItemsLibrary;
            using Microsoft.Win32;
            using System.Windows;
            using System.Windows.Controls;
            using System.Windows.Controls.Primitives;
            using System.Windows.Data;
            using System.Windows.Documents;
            using System.Windows.Input;
            using System.Windows.Media;
            using System.Windows.Media.ProGPU;
            using System.Windows.Media.Imaging;
            using System.Windows.Threading;

            namespace ExternalSdkDefaultItemsApp;

            public sealed class DefaultItemsItem
            {
                public string Name { get; set; } = string.Empty;

                public string Kind { get; set; } = string.Empty;

                public bool IsActive { get; set; }
            }

            public sealed class DefaultItemsLargeItem
            {
                public DefaultItemsLargeItem(int index, string name, string kind, bool isActive)
                {
                    Index = index;
                    Name = name;
                    Kind = kind;
                    IsActive = isActive;
                }

                public int Index { get; set; }

                public string Name { get; set; }

                public string Kind { get; set; }

                public bool IsActive { get; set; }
            }

            public sealed class DefaultItemsNode
            {
                public string Name { get; set; } = string.Empty;

                public ObservableCollection<DefaultItemsNode> Children { get; } =
                    new ObservableCollection<DefaultItemsNode>();
            }

            public sealed class DefaultItemsProviderSource
            {
                public string CreateText()
                {
                    return "Default item object provider text";
                }
            }

            public static class DefaultItemsCompositeProvider
            {
                public static ObservableCollection<string> Items { get; } =
                    new ObservableCollection<string>
                    {
                        "Default item composite alpha",
                        "Default item composite beta",
                    };
            }

            public sealed class DefaultItemsViewModel : INotifyPropertyChanged
            {
                private string _status = "Default item binding ready";
                private string? _optionalStatus;
                private bool _isFormOptionEnabled = true;
                private double _formProgress = 25.0;
                private DateTime? _selectedDate = new DateTime(2026, 6, 24);
                private DefaultItemsItem _selectedItem;
                private DefaultItemsLargeItem _selectedLargeItem;

                public event PropertyChangedEventHandler PropertyChanged = delegate { };

                public ObservableCollection<DefaultItemsItem> Items { get; } =
                    new ObservableCollection<DefaultItemsItem>
                    {
                        new DefaultItemsItem
                        {
                            Name = "Default item alpha",
                            Kind = "Framework",
                            IsActive = true,
                        },
                        new DefaultItemsItem
                        {
                            Name = "Default item beta",
                            Kind = "Data",
                            IsActive = false,
                        },
                    };

                public ObservableCollection<DefaultItemsLargeItem> LargeItems { get; } =
                    CreateLargeItems();

                public ObservableCollection<DefaultItemsNode> Nodes { get; } =
                    new ObservableCollection<DefaultItemsNode>
                    {
                        new DefaultItemsNode
                        {
                            Name = "Default item root",
                            Children =
                            {
                                new DefaultItemsNode { Name = "Default item child" },
                            },
                        },
                    };

                public DefaultItemsViewModel()
                {
                    _selectedItem = Items[0];
                    _selectedLargeItem = LargeItems[0];
                }

                public string Status
                {
                    get => _status;
                    set
                    {
                        if (string.Equals(_status, value, StringComparison.Ordinal))
                        {
                            return;
                        }

                        _status = value;
                        OnPropertyChanged();
                    }
                }

                public DefaultItemsItem SelectedItem
                {
                    get => _selectedItem;
                    set
                    {
                        if (ReferenceEquals(_selectedItem, value))
                        {
                            return;
                        }

                        _selectedItem = value;
                        OnPropertyChanged();
                    }
                }

                public DefaultItemsLargeItem SelectedLargeItem
                {
                    get => _selectedLargeItem;
                    set
                    {
                        if (ReferenceEquals(_selectedLargeItem, value))
                        {
                            return;
                        }

                        _selectedLargeItem = value;
                        OnPropertyChanged();
                    }
                }

                public string? OptionalStatus
                {
                    get => _optionalStatus;
                    set
                    {
                        if (string.Equals(_optionalStatus, value, StringComparison.Ordinal))
                        {
                            return;
                        }

                        _optionalStatus = value;
                        OnPropertyChanged();
                    }
                }

                public bool IsFormOptionEnabled
                {
                    get => _isFormOptionEnabled;
                    set
                    {
                        if (_isFormOptionEnabled == value)
                        {
                            return;
                        }

                        _isFormOptionEnabled = value;
                        OnPropertyChanged();
                    }
                }

                public double FormProgress
                {
                    get => _formProgress;
                    set
                    {
                        if (Math.Abs(_formProgress - value) < 0.001)
                        {
                            return;
                        }

                        _formProgress = value;
                        OnPropertyChanged();
                    }
                }

                public DateTime? SelectedDate
                {
                    get => _selectedDate;
                    set
                    {
                        if (Nullable.Equals(_selectedDate, value))
                        {
                            return;
                        }

                        _selectedDate = value;
                        OnPropertyChanged();
                    }
                }

                private void OnPropertyChanged([CallerMemberName] string propertyName = "")
                {
                    PropertyChanged(this, new PropertyChangedEventArgs(propertyName));
                }

                private static ObservableCollection<DefaultItemsLargeItem> CreateLargeItems()
                {
                    var items = new ObservableCollection<DefaultItemsLargeItem>();
                    string[] kinds =
                    {
                        "Framework",
                        "Rendering",
                        "Toolkit",
                        "SDK",
                    };

                    for (int i = 0; i < 100_000; i++)
                    {
                        int index = i + 1;
                        items.Add(
                            new DefaultItemsLargeItem(
                                index,
                                $"External default row {index:000000}",
                                kinds[i % kinds.Length],
                                i % 2 == 0));
                    }

                    return items;
                }
            }

            public sealed class DefaultItemsItemNameConverter : IValueConverter
            {
                public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
                {
                    return value is DefaultItemsItem item ? $"Selected: {item.Name}" : string.Empty;
                }

                public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
                {
                    return Binding.DoNothing;
                }
            }

            public sealed class DefaultItemsStatusSelectionConverter : IMultiValueConverter
            {
                public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
                {
                    var status = values.Length > 0 ? values[0] as string : null;
                    var selectedName = values.Length > 1 ? values[1] as string : null;
                    return $"Composite: {status ?? string.Empty} / {selectedName ?? string.Empty}";
                }

                public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
                {
                    var results = new object[targetTypes.Length];
                    Array.Fill(results, Binding.DoNothing);
                    return results;
                }
            }

            public sealed class DefaultItemsNameTemplateSelector : DataTemplateSelector
            {
                public override DataTemplate SelectTemplate(object item, DependencyObject container)
                {
                    if (item is DefaultItemsItem selectedItem && container is FrameworkElement element)
                    {
                        string resourceKey = selectedItem.Name.Contains("beta", StringComparison.OrdinalIgnoreCase)
                            ? "DefaultItemsSelectedBetaTemplate"
                            : "DefaultItemsSelectedAlphaTemplate";
                        return RequireType<DataTemplate>(
                            element.FindResource(resourceKey),
                            $"default-item template selector resource {resourceKey}");
                    }

                    return base.SelectTemplate(item, container);
                }

                private static T RequireType<T>(object value, string description)
                {
                    return value is T typed
                        ? typed
                        : throw new InvalidOperationException($"Expected {description} to be {typeof(T).FullName}.");
                }
            }

            public sealed class DefaultItemsRequiredTextRule : ValidationRule
            {
                public override ValidationResult Validate(object value, CultureInfo cultureInfo)
                {
                    return string.IsNullOrWhiteSpace(value as string)
                        ? new ValidationResult(false, "Default item text is required.")
                        : ValidationResult.ValidResult;
                }
            }

            public partial class MainWindow : Window
            {
                public static RoutedUICommand DefaultItemsCommand { get; } =
                    new RoutedUICommand(
                        "Default Items Command",
                        nameof(DefaultItemsCommand),
                        typeof(MainWindow));

                private const string DefaultItemsLiveGeometryValidationEnvironmentVariable =
                    "PROGPU_WPF_EXTERNAL_DEFAULT_LIVE_GEOMETRY_VALIDATE";
                private const int DefaultItemsLiveGeometryValidationMaxAttempts = 1000;
                private static readonly TimeSpan DefaultItemsLiveGeometryValidationRetryDelay =
                    TimeSpan.FromMilliseconds(16);
                private bool _defaultItemsLiveGeometryValidationStarted;

                public int LoadedCount { get; private set; }

                public int ButtonClickCount { get; private set; }

                public int CommandExecutionCount { get; private set; }

                public int EventSetterClickCount { get; private set; }

                public int ExpanderExpandedCount { get; private set; }

                public int ExpanderCollapsedCount { get; private set; }

                public int MenuClickCount { get; private set; }

                public int MenuCheckedCount { get; private set; }

                public int MenuUncheckedCount { get; private set; }

                public int ContextMenuClickCount { get; private set; }

                public int ContextMenuCheckedCount { get; private set; }

                public int ContextMenuUncheckedCount { get; private set; }

                public int RadioButtonCheckedCount { get; private set; }

                public string LastRadioButtonCheckedName { get; private set; } = string.Empty;

                public int PasswordChangedCount { get; private set; }

                public string LastPasswordValue { get; private set; } = string.Empty;

                public string LastCommandParameter { get; private set; } = string.Empty;

                public int BindingTargetUpdatedCount { get; private set; }

                public string LastBindingTargetUpdatedName { get; private set; } = string.Empty;

                public string LastBindingTargetUpdatedPropertyName { get; private set; } = string.Empty;

                public int BindingSourceUpdatedCount { get; private set; }

                public string LastBindingSourceUpdatedName { get; private set; } = string.Empty;

                public string LastBindingSourceUpdatedPropertyName { get; private set; } = string.Empty;

                public DefaultItemsViewModel ViewModel { get; } = new DefaultItemsViewModel();

                public MainWindow()
                {
                    InitializeComponent();
                    DataContext = ViewModel;
                    if (Environment.GetEnvironmentVariable(DefaultItemsLiveGeometryValidationEnvironmentVariable) == "1")
                    {
                        Loaded += OnDefaultItemsLiveGeometryValidationLoaded;
                        StartDefaultItemsLiveGeometryValidationIfRequired();
                    }
                }

                private void OnDefaultItemsLiveGeometryValidationLoaded(object sender, RoutedEventArgs e)
                {
                    StartDefaultItemsLiveGeometryValidationIfRequired();
                }

                private void StartDefaultItemsLiveGeometryValidationIfRequired()
                {
                    if (_defaultItemsLiveGeometryValidationStarted ||
                        Environment.GetEnvironmentVariable(DefaultItemsLiveGeometryValidationEnvironmentVariable) != "1")
                    {
                        return;
                    }

                    _defaultItemsLiveGeometryValidationStarted = true;
                    _ = Task.Run(
                        async () =>
                        {
                            try
                            {
                                await ValidateRequiredDefaultItemsLiveGeometryAsync().ConfigureAwait(false);
                            }
                            catch (Exception ex)
                            {
                                Console.Error.WriteLine(ex);
                                Environment.Exit(1);
                            }
                        });
                }

                private async Task ValidateRequiredDefaultItemsLiveGeometryAsync()
                {
                    for (int attempt = 0; attempt < DefaultItemsLiveGeometryValidationMaxAttempts; attempt++)
                    {
                        await Task.Delay(DefaultItemsLiveGeometryValidationRetryDelay).ConfigureAwait(false);
                        if (!ProGpuWpfDiagnostics.TryGetWindowHost(this, out var liveHost) ||
                            liveHost == null)
                        {
                            continue;
                        }

                        if (!liveHost.HasPresentedFrame)
                        {
                            WakeDefaultItemsLiveHost();
                            continue;
                        }

                        WakeDefaultItemsLiveHost();
                        string status = await Dispatcher.InvokeAsync(
                            ValidateDefaultItemsLiveRenderSurfaceGeometryCore,
                            DispatcherPriority.Send);
                        Console.WriteLine($"External SDK default-item apphost live geometry validation succeeded: {status}.");
                        Environment.Exit(0);
                        return;
                    }

                    Console.Error.WriteLine(
                        "Expected the external SDK default-item apphost to present a stable ProGPU frame before live geometry validation.");
                    Environment.Exit(1);
                }

                private string ValidateDefaultItemsLiveRenderSurfaceGeometryCore()
                {
                    if (!ProGpuWpfDiagnostics.TryGetRenderSurfaceGeometry(this, out var geometry))
                    {
                        throw new InvalidOperationException("Expected default-item live ProGPU WPF host geometry.");
                    }

                    Require(geometry.LogicalWidth == 260u, "Expected default-item live ProGPU WPF logical width.");
                    Require(geometry.LogicalHeight == 140u, "Expected default-item live ProGPU WPF logical height.");
                    if (geometry.PixelWidth < geometry.LogicalWidth || geometry.PixelHeight < geometry.LogicalHeight)
                    {
                        throw new InvalidOperationException(
                            $"Expected default-item live ProGPU WPF pixels to cover logical content, but got logical {geometry.LogicalWidth}x{geometry.LogicalHeight} and pixels {geometry.PixelWidth}x{geometry.PixelHeight}.");
                    }

                    if (geometry.ViewportX != 0 ||
                        geometry.ViewportY != 0 ||
                        geometry.ViewportWidth != geometry.PixelWidth ||
                        geometry.ViewportHeight != geometry.PixelHeight)
                    {
                        throw new InvalidOperationException(
                            $"Expected default-item live ProGPU WPF viewport to use the full physical target, but got viewport {geometry.ViewportWidth}x{geometry.ViewportHeight}@{geometry.ViewportX},{geometry.ViewportY} for pixels {geometry.PixelWidth}x{geometry.PixelHeight}.");
                    }

                    return $"logical {geometry.LogicalWidth}x{geometry.LogicalHeight}, pixels {geometry.PixelWidth}x{geometry.PixelHeight}, viewport {geometry.ViewportWidth}x{geometry.ViewportHeight}@{geometry.ViewportX},{geometry.ViewportY}, dpi {geometry.DpiScale:0.###}";
                }

                private void WakeDefaultItemsLiveHost()
                {
                    ProGpuWpfDiagnostics.TryRequestRender(this);
                    ProGpuWpfDiagnostics.TryWakeNativeLoop(this);
                }

                public void ValidateDefaultItemsRun()
                {
                    Require(DefaultItemsTitleText.Text == "Default item resource text", "Expected default-item StaticResource text.");
                    var foreground = RequireType<SolidColorBrush>(DefaultItemsTitleText.Foreground, "default-item DynamicResource brush");
                    Require(
                        foreground.Color == Color.FromRgb(0x33, 0x55, 0x77),
                        "Expected default-item DynamicResource brush color.");
                    Application.Current.Resources["DefaultItemsBrush"] =
                        new SolidColorBrush(Color.FromRgb(0x88, 0x22, 0x11));
                    DrainDispatcher();
                    var updatedForeground = RequireType<SolidColorBrush>(
                        DefaultItemsTitleText.Foreground,
                        "default-item updated DynamicResource brush");
                    Require(
                        updatedForeground.Color == Color.FromRgb(0x88, 0x22, 0x11),
                        "Expected default-item DynamicResource brush invalidation.");
                    Require(
                        DefaultItemsAppDictionaryText.Text == "Default item app dictionary text",
                        "Expected default-item app resource dictionary text.");
                    var appDictionaryForeground = RequireType<SolidColorBrush>(
                        DefaultItemsAppDictionaryText.Foreground,
                        "default-item app resource dictionary brush");
                    Require(
                        appDictionaryForeground.Color == Color.FromRgb(0x44, 0x77, 0x99),
                        "Expected default-item app resource dictionary brush color.");
                    Application.Current.Resources["DefaultItemsAppDictionaryBrush"] =
                        new SolidColorBrush(Color.FromRgb(0x22, 0x88, 0x44));
                    DrainDispatcher();
                    var updatedAppDictionaryForeground = RequireType<SolidColorBrush>(
                        DefaultItemsAppDictionaryText.Foreground,
                        "default-item updated app resource dictionary brush");
                    Require(
                        updatedAppDictionaryForeground.Color == Color.FromRgb(0x22, 0x88, 0x44),
                        "Expected default-item app DynamicResource brush invalidation.");
                    var defaultItemsFreezableBrush = RequireType<SolidColorBrush>(
                        Resources["DefaultItemsFreezableBrush"],
                        "default-item Freezable brush resource");
                    Require(
                        defaultItemsFreezableBrush.Color == Color.FromRgb(0x5B, 0x8C, 0x7A)
                            && Math.Abs(defaultItemsFreezableBrush.Opacity - 0.75) < 0.001
                            && defaultItemsFreezableBrush.CanFreeze,
                        "Expected default-item Freezable brush metadata.");
                    if (!defaultItemsFreezableBrush.IsFrozen)
                    {
                        defaultItemsFreezableBrush.Freeze();
                    }

                    Require(
                        defaultItemsFreezableBrush.IsFrozen,
                        "Expected default-item Freezable brush frozen state.");
                    var defaultItemsFreezableClone = defaultItemsFreezableBrush.Clone();
                    defaultItemsFreezableClone.Opacity = 0.33;
                    Require(
                        !defaultItemsFreezableClone.IsFrozen
                            && Math.Abs(defaultItemsFreezableClone.Opacity - 0.33) < 0.001
                            && Math.Abs(defaultItemsFreezableBrush.Opacity - 0.75) < 0.001,
                        "Expected default-item Freezable brush clone mutability.");
                    var defaultItemsUnsharedBrushA = RequireType<SolidColorBrush>(
                        Resources["DefaultItemsUnsharedBrush"],
                        "default-item x:Shared=false first brush");
                    var defaultItemsUnsharedBrushB = RequireType<SolidColorBrush>(
                        Resources["DefaultItemsUnsharedBrush"],
                        "default-item x:Shared=false second brush");
                    Require(
                        !ReferenceEquals(defaultItemsUnsharedBrushA, defaultItemsUnsharedBrushB)
                            && defaultItemsUnsharedBrushA.Color == Color.FromRgb(0xC4, 0x5A, 0x2B)
                            && defaultItemsUnsharedBrushB.Color == Color.FromRgb(0xC4, 0x5A, 0x2B),
                        "Expected default-item x:Shared=false resource lookup.");
                    Require(
                        DefaultItemsLibraryResourceText.Text == "Default item library resource text",
                        "Expected default-item referenced library component resource text.");
                    var libraryResourceForeground = RequireType<SolidColorBrush>(
                        DefaultItemsLibraryResourceText.Foreground,
                        "default-item referenced library component resource brush");
                    Require(
                        libraryResourceForeground.Color == Color.FromRgb(0x76, 0x54, 0x32),
                        "Expected default-item referenced library component resource brush color.");
                    var defaultItemsImageSource = RequireType<BitmapSource>(
                        DefaultItemsImage.Source,
                        "default-item XAML resource image source");
                    Require(
                        defaultItemsImageSource.PixelWidth == 2
                            && defaultItemsImageSource.PixelHeight == 2
                            && defaultItemsImageSource.Format == PixelFormats.Bgra32,
                        "Expected default-item XAML resource image metadata.");
                    byte[] imagePixels = new byte[16];
                    defaultItemsImageSource.CopyPixels(imagePixels, 8, 0);
                    Require(
                        imagePixels[2] == 0xFF && imagePixels[15] == 0xFF,
                        "Expected default-item XAML resource image pixels.");
                    var imageBrush = RequireType<ImageBrush>(
                        DefaultItemsImageBrushRectangle.Fill,
                        "default-item ImageBrush fill");
                    var imageBrushSource = RequireType<BitmapSource>(
                        imageBrush.ImageSource,
                        "default-item ImageBrush source");
                    Require(
                        imageBrushSource.PixelWidth == 2
                            && imageBrushSource.PixelHeight == 2
                            && imageBrushSource.Format == PixelFormats.Bgra32,
                        "Expected default-item ImageBrush image metadata.");
                    byte[] imageBrushPixels = new byte[16];
                    imageBrushSource.CopyPixels(imageBrushPixels, 8, 0);
                    Require(
                        imageBrushPixels[5] == 0xFF && imageBrushPixels[15] == 0xFF,
                        "Expected default-item ImageBrush image pixels.");
                    Require(
                        DefaultItemsCursorTarget.Cursor is not null,
                        "Expected default-item XAML cursor resource.");
                    var cursorResourceInfo = Application.GetResourceStream(
                        new Uri("Assets/DefaultItemsCursor.cur", UriKind.Relative));
                    Require(
                        cursorResourceInfo?.Stream is not null,
                        "Expected default-item cursor pack resource stream.");
                    using (cursorResourceInfo.Stream)
                    using (var cursor = new Cursor(cursorResourceInfo.Stream))
                    {
                        Require(cursor is not null, "Expected default-item cursor stream load.");
                    }
                    Require(
                        !DefaultItemsRichTextBox.IsReadOnly,
                        "Expected default-item RichTextBox metadata.");
                    Require(
                        ReferenceEquals(DefaultItemsCopyRichTextButton.Command, ApplicationCommands.Copy)
                            && ReferenceEquals(DefaultItemsCopyRichTextButton.CommandTarget, DefaultItemsRichTextBox)
                            && ReferenceEquals(DefaultItemsPasteRichTextButton.Command, ApplicationCommands.Paste)
                            && ReferenceEquals(DefaultItemsPasteRichTextButton.CommandTarget, DefaultItemsRichTextBox),
                        "Expected default-item RichTextBox XAML command metadata.");
                    var richDocument = RequireType<FlowDocument>(
                        DefaultItemsRichTextBox.Document,
                        "default-item RichTextBox FlowDocument");
                    Require(
                        richDocument.Blocks.Count >= 3,
                        "Expected default-item RichTextBox FlowDocument block metadata.");
                    var richParagraph = RequireType<Paragraph>(
                        richDocument.Blocks.FirstBlock,
                        "default-item RichTextBox Paragraph");
                    var richRun = richParagraph.Inlines
                        .OfType<Run>()
                        .FirstOrDefault(run => run.Text.Contains("Default item", StringComparison.Ordinal));
                    var richBold = richParagraph.Inlines
                        .OfType<Bold>()
                        .FirstOrDefault();
                    var richItalic = richParagraph.Inlines
                        .OfType<Italic>()
                        .FirstOrDefault();
                    Require(
                        richRun is not null && richBold is not null && richItalic is not null,
                        "Expected default-item RichTextBox paragraph inline types.");
                    richBold = RequireType<Bold>(
                        richBold,
                        "default-item RichTextBox Bold inline");
                    var richBoldRun = RequireType<Run>(
                        richBold.Inlines.FirstInline,
                        "default-item RichTextBox Bold run");
                    richItalic = RequireType<Italic>(
                        richItalic,
                        "default-item RichTextBox Italic inline");
                    var richItalicRun = RequireType<Run>(
                        richItalic.Inlines.FirstInline,
                        "default-item RichTextBox Italic run");
                    Require(
                        richRun.Text.Contains("Default item", StringComparison.Ordinal)
                            && richBoldRun.Text == "rich text"
                            && richItalicRun.Text == " italic text",
