                private static void DrainDispatcher()
                {
                    var frame = new DispatcherFrame();
                    Dispatcher.CurrentDispatcher.BeginInvoke(
                        DispatcherPriority.ApplicationIdle,
                        new Action(() => frame.Continue = false));
                    Dispatcher.PushFrame(frame);
                }

                private static void PumpDispatcherUntil(Func<bool> condition, string description)
                {
                    var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(2);
                    while (!condition())
                    {
                        DrainDispatcher();
                        if (condition())
                        {
                            return;
                        }

                        if (DateTime.UtcNow >= deadline)
                        {
                            throw new InvalidOperationException($"Timed out waiting for {description}.");
                        }
                    }
                }

                private static T? FindVisualDescendantByName<T>(DependencyObject root, string name)
                    where T : FrameworkElement
                {
                    int childCount = VisualTreeHelper.GetChildrenCount(root);
                    for (int i = 0; i < childCount; i++)
                    {
                        DependencyObject child = VisualTreeHelper.GetChild(root, i);
                        if (child is T typed && string.Equals(typed.Name, name, StringComparison.Ordinal))
                        {
                            return typed;
                        }

                        T? nested = FindVisualDescendantByName<T>(child, name);
                        if (nested is not null)
                        {
                            return nested;
                        }
                    }

                    return null;
                }

                private static T? FindVisualDescendant<T>(DependencyObject root)
                    where T : DependencyObject
                {
                    int childCount = VisualTreeHelper.GetChildrenCount(root);
                    for (int i = 0; i < childCount; i++)
                    {
                        DependencyObject child = VisualTreeHelper.GetChild(root, i);
                        if (child is T typed)
                        {
                            return typed;
                        }

                        T? nested = FindVisualDescendant<T>(child);
                        if (nested is not null)
                        {
                            return nested;
                        }
                    }

                    return null;
                }

                private static int CountVisualDescendants<T>(DependencyObject root)
                    where T : DependencyObject
                {
                    int count = 0;
                    int childCount = VisualTreeHelper.GetChildrenCount(root);
                    for (int i = 0; i < childCount; i++)
                    {
                        DependencyObject child = VisualTreeHelper.GetChild(root, i);
                        if (child is T)
                        {
                            count++;
                        }

                        count += CountVisualDescendants<T>(child);
                    }

                    return count;
                }

                private void ValidateDefaultItemsMessageBox()
                {
                    Type serviceType = typeof(MessageBox).Assembly.GetType(
                            "System.Windows.PortableMessageBoxService",
                            throwOnError: false)
                        ?? throw new TypeLoadException("System.Windows.PortableMessageBoxService");
                    var isEnabledProperty = serviceType.GetProperty(
                            "IsEnabled",
                            BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? throw new MissingMemberException(serviceType.FullName, "IsEnabled");
                    if (!OperatingSystem.IsWindows())
                    {
                        Require(
                            (bool)(isEnabledProperty.GetValue(null) ?? false),
                            "Expected default-item portable MessageBox service to be enabled.");
                    }

                    IDisposable? registration = RegisterDefaultItemsDeterministicMessageBox(serviceType);
                    try
                    {
                        var noOwnerResult = MessageBox.Show(
                            "default-item SDK message",
                            "default-item SDK caption",
                            MessageBoxButton.YesNoCancel,
                            MessageBoxImage.Warning,
                            MessageBoxResult.No,
                            MessageBoxOptions.None);
                        Require(
                            noOwnerResult == MessageBoxResult.No,
                            "Expected default-item MessageBox no-owner default result.");

                        var ownerResult = MessageBox.Show(
                            this,
                            "default-item SDK owner message",
                            "default-item SDK owner caption",
                            MessageBoxButton.OKCancel,
                            MessageBoxImage.Information,
                            MessageBoxResult.None,
                            MessageBoxOptions.None);
                        Require(
                            ownerResult == MessageBoxResult.OK,
                            "Expected default-item MessageBox owner fallback result.");
                    }
                    finally
                    {
                        registration?.Dispose();
                    }
                }

                private static IDisposable? RegisterDefaultItemsDeterministicMessageBox(Type serviceType)
                {
                    var registerMethod = serviceType.GetMethod(
                            "Register",
                            BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic,
                            binder: null,
                            types: new[] { typeof(Func<object, object>) },
                            modifiers: null)
                        ?? throw new MissingMethodException(serviceType.FullName, "Register");

                    return registerMethod.Invoke(
                        null,
                        new object[] { (Func<object, object>)ShowDefaultItemsDeterministicMessageBox }) as IDisposable;
                }

                private static object ShowDefaultItemsDeterministicMessageBox(object request)
                {
                    return ReadDefaultItemsPortableRequestString(request, "FallbackResult");
                }

                private static void ValidateDefaultItemsPrintDialog()
                {
                    if (OperatingSystem.IsWindows())
                    {
                        return;
                    }

                    var printDialog = new PrintDialog
                    {
                        UserPageRangeEnabled = true,
                        SelectedPagesEnabled = true,
                        CurrentPageEnabled = true,
                        PageRangeSelection = PageRangeSelection.UserPages,
                        PageRange = new PageRange(9, 4),
                        MinPage = 2,
                        MaxPage = 12
                    };

                    Require(printDialog.UserPageRangeEnabled, "Expected default-item PrintDialog user page range enabled.");
                    Require(printDialog.SelectedPagesEnabled, "Expected default-item PrintDialog selected pages enabled.");
                    Require(printDialog.CurrentPageEnabled, "Expected default-item PrintDialog current page enabled.");
                    Require(
                        printDialog.PageRangeSelection == PageRangeSelection.UserPages,
                        "Expected default-item PrintDialog page range selection.");
                    Require(printDialog.PageRange.PageFrom == 4, "Expected default-item PrintDialog normalized page range start.");
                    Require(printDialog.PageRange.PageTo == 9, "Expected default-item PrintDialog normalized page range end.");
                    Require(printDialog.MinPage == 2u, "Expected default-item PrintDialog minimum page.");
                    Require(printDialog.MaxPage == 12u, "Expected default-item PrintDialog maximum page.");
                    Require(printDialog.PrintQueue is null, "Expected default-item PrintDialog portable print queue.");
                    Require(printDialog.PrintTicket is not null, "Expected default-item PrintDialog portable print ticket.");
                    Require(
                        Math.Abs(printDialog.PrintableAreaWidth - 816.0) < 0.001,
                        "Expected default-item PrintDialog portable printable width.");
                    Require(
                        Math.Abs(printDialog.PrintableAreaHeight - 1056.0) < 0.001,
                        "Expected default-item PrintDialog portable printable height.");
                    Require(
                        printDialog.ShowDialog().GetValueOrDefault(true) == false,
                        "Expected default-item PrintDialog portable dialog result.");
                }

                private static void ValidateDefaultItemsClipboard()
                {
                    Clipboard.Clear();
                    Require(!Clipboard.ContainsText(), "Expected default-item Clipboard initial text state.");

                    Clipboard.SetText("default-item SDK clipboard text");
                    Require(Clipboard.ContainsText(), "Expected default-item Clipboard text state after SetText.");
                    Require(
                        Clipboard.GetText() == "default-item SDK clipboard text",
                        "Expected default-item Clipboard GetText.");
                    var textDataObject = Clipboard.GetDataObject()
                        ?? throw new InvalidOperationException("Expected default-item Clipboard data object.");
                    Require(
                        Equals(textDataObject.GetData(DataFormats.UnicodeText), "default-item SDK clipboard text"),
                        "Expected default-item Clipboard data object Unicode text.");
                    Require(Clipboard.IsCurrent(textDataObject), "Expected default-item Clipboard current text data object.");
                    Clipboard.Flush();
                    Require(
                        Clipboard.GetText() == "default-item SDK clipboard text",
                        "Expected default-item Clipboard flushed text.");

                    var customDataObject = new DataObject();
                    customDataObject.SetData(
                        DataFormats.UnicodeText,
                        "default-item SDK data object text",
                        autoConvert: false);
                    customDataObject.SetData(
                        "DefaultItemsCustomFormat",
                        "default-item SDK custom payload",
                        autoConvert: false);
                    Clipboard.SetDataObject(customDataObject, copy: true);
                    Require(Clipboard.ContainsText(), "Expected default-item Clipboard data object text state.");
                    Require(
                        Clipboard.GetText() == "default-item SDK data object text",
                        "Expected default-item Clipboard data object text.");
                    Require(
                        Equals(Clipboard.GetData("DefaultItemsCustomFormat"), "default-item SDK custom payload"),
                        "Expected default-item Clipboard custom data format.");
                    var currentDataObject = RequireType<DataObject>(
                        Clipboard.GetDataObject(),
                        "default-item Clipboard current data object after SetDataObject");
                    Require(
                        currentDataObject.GetDataPresent("DefaultItemsCustomFormat", autoConvert: false),
                        "Expected default-item Clipboard custom format present.");
                    Require(
                        Equals(
                            currentDataObject.GetData("DefaultItemsCustomFormat", autoConvert: false),
                            "default-item SDK custom payload"),
                        "Expected default-item Clipboard custom data object payload.");
                    Require(
                        currentDataObject.TryGetData(
                            "DefaultItemsCustomFormat",
                            autoConvert: false,
                            out string typedCustomPayload),
                        "Expected default-item Clipboard typed custom data retrieval state.");
                    Require(
                        typedCustomPayload == "default-item SDK custom payload",
                        "Expected default-item Clipboard typed custom data retrieval.");
                    Require(
                        Clipboard.IsCurrent(currentDataObject),
                        "Expected default-item Clipboard SetDataObject current state.");

                    var fileDropList = new StringCollection
                    {
                        "/tmp/default-item-alpha.txt",
                        "/tmp/default-item-beta.txt"
                    };
                    Clipboard.SetFileDropList(fileDropList);
                    Require(Clipboard.ContainsFileDropList(), "Expected default-item Clipboard file-drop state.");
                    var roundTripFileDropList = Clipboard.GetFileDropList();
                    Require(roundTripFileDropList.Count == 2, "Expected default-item Clipboard file-drop count.");
                    Require(
                        roundTripFileDropList[0] == "/tmp/default-item-alpha.txt",
                        "Expected default-item Clipboard first file-drop item.");
                    Require(
                        roundTripFileDropList[1] == "/tmp/default-item-beta.txt",
                        "Expected default-item Clipboard second file-drop item.");

                    Clipboard.Clear();
                    Require(!Clipboard.ContainsText(), "Expected default-item Clipboard cleared text state.");
                    Require(!Clipboard.ContainsFileDropList(), "Expected default-item Clipboard cleared file-drop state.");
                    Require(Clipboard.GetText() == string.Empty, "Expected default-item Clipboard cleared text.");
                }

                private void ValidateDefaultItemsFileDialogs()
                {
                    Type serviceType = typeof(OpenFileDialog).Assembly.GetType(
                            "Microsoft.Win32.PortableFileDialogService",
                            throwOnError: false)
                        ?? throw new TypeLoadException("Microsoft.Win32.PortableFileDialogService");
                    var isEnabledProperty = serviceType.GetProperty(
                            "IsEnabled",
                            BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
                        ?? throw new MissingMemberException(serviceType.FullName, "IsEnabled");
                    if (!OperatingSystem.IsWindows())
                    {
                        Require(
                            (bool)(isEnabledProperty.GetValue(null) ?? false),
                            "Expected default-item portable file dialog service to be enabled.");
                    }

                    var registerMethod = serviceType.GetMethod(
                            "Register",
                            BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic,
                            binder: null,
                            types: new[] { typeof(Func<object, string?>) },
                            modifiers: null)
                        ?? throw new MissingMethodException(serviceType.FullName, "Register");

                    string tempDirectory = Path.Combine(
                        Path.GetTempPath(),
                        "progpu-wpf-default-items-file-dialog-" + Guid.NewGuid().ToString("N"));
                    Directory.CreateDirectory(tempDirectory);
                    string openPath = Path.Combine(tempDirectory, "open.txt");
                    string savePathWithoutExtension = Path.Combine(tempDirectory, "saved");
                    string savePath = savePathWithoutExtension + ".txt";
                    File.WriteAllText(openPath, "default-item SDK file dialog");

                    int requestCount = 0;
                    var seenKinds = new List<string>();
                    Func<object, string?> handler = request =>
                    {
                        string kind = ReadDefaultItemsPortableRequestString(request, "Kind");
                        seenKinds.Add(kind);
                        requestCount++;

                        return kind switch
                        {
                            "SaveFile" => savePathWithoutExtension,
                            "PickFolder" => tempDirectory,
                            _ => openPath
                        };
                    };

                    IDisposable? registration = null;
                    try
                    {
                        registration = (IDisposable?)registerMethod.Invoke(null, new object[] { handler });

                        var openDialog = new OpenFileDialog
                        {
                            Filter = "Text files (*.txt)|*.txt|All files (*.*)|*.*"
                        };
                        Require(openDialog.ShowDialog() == true, "Expected default-item OpenFileDialog result.");
                        Require(openDialog.FileName == openPath, "Expected default-item OpenFileDialog FileName.");
                        Require(openDialog.SafeFileName == "open.txt", "Expected default-item OpenFileDialog SafeFileName.");

                        var saveDialog = new SaveFileDialog
                        {
                            DefaultExt = "txt",
                            OverwritePrompt = false
                        };
                        Require(saveDialog.ShowDialog(this) == true, "Expected default-item owner SaveFileDialog result.");
                        Require(saveDialog.FileName == savePath, "Expected default-item owner SaveFileDialog FileName.");
                        Require(saveDialog.SafeFileName == "saved.txt", "Expected default-item owner SaveFileDialog SafeFileName.");

                        var folderDialog = new OpenFolderDialog();
                        Require(folderDialog.ShowDialog(this) == true, "Expected default-item owner OpenFolderDialog result.");
                        Require(folderDialog.FolderName == tempDirectory, "Expected default-item owner OpenFolderDialog FolderName.");
                        Require(
                            folderDialog.SafeFolderName == Path.GetFileName(tempDirectory),
                            "Expected default-item owner OpenFolderDialog SafeFolderName.");

                        Require(requestCount == 3, "Expected default-item file dialog request count.");
                        Require(seenKinds[0] == "OpenFile", "Expected default-item file dialog open request kind.");
                        Require(seenKinds[1] == "SaveFile", "Expected default-item file dialog save request kind.");
                        Require(seenKinds[2] == "PickFolder", "Expected default-item file dialog folder request kind.");
                    }
                    finally
                    {
                        registration?.Dispose();
                        Directory.Delete(tempDirectory, recursive: true);
                    }
                }

                private static string ReadDefaultItemsPortableRequestString(object request, string propertyName)
                {
                    return request.GetType()
                        .GetProperty(propertyName, BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic)
                        ?.GetValue(request)
                        ?.ToString()
                        ?? string.Empty;
                }

                private static T RequireType<T>(object? value, string description)
                {
                    return value is T typed
                        ? typed
                        : throw new InvalidOperationException($"Expected {description} to be {typeof(T).FullName}.");
                }

                private static void Require(bool condition, string message)
                {
                    if (!condition)
                    {
                        throw new InvalidOperationException(message);
                    }
                }
            }
            """);

        return appProjectPath;
    }

    private static void ValidateExternalProjectShape(string workRoot)
    {
        string appProject = File.ReadAllText(Path.Combine(workRoot, AppAssemblyName, AppAssemblyName + ".csproj"));
        string libraryProject = File.ReadAllText(Path.Combine(workRoot, LibraryAssemblyName, LibraryAssemblyName + ".csproj"));
        string localizationProject = File.ReadAllText(Path.Combine(workRoot, LocalizationAssemblyName, LocalizationAssemblyName + ".csproj"));

        AssertContains(appProject, $"<Project Sdk=\"LibreWPF.Sdk/{SdkVersion}\">", "external app SDK");
        AssertDoesNotContain(appProject, $"<Project Sdk=\"{OriginalWpfSdk}\">", "external app original SDK");
        AssertDoesNotContain(appProject, $"<Project Sdk=\"{OriginalWindowsDesktopWpfSdk}\">", "external app original WindowsDesktop SDK");
        AssertContains(appProject, $"<AssemblyName>{AppOutputAssemblyName}</AssemblyName>", "external app custom assembly name");
        AssertContains(appProject, "<OutputType>WinExe</OutputType>", "external app output type");
        AssertContains(appProject, $"<TargetFramework>{ExternalAppTargetFramework}</TargetFramework>", "external app Windows target framework");
        AssertContains(appProject, "<EnableDefaultItems>false</EnableDefaultItems>", "external app explicit item mode");
        AssertContains(appProject, "<UseWPF>true</UseWPF>", "external app WPF property");
        AssertContains(appProject, "<Compile Include=\"**/*.cs\" />", "external app explicit compile items");
        AssertContains(appProject, "<ApplicationDefinition Include=\"App.xaml\" />", "external app explicit application definition item");
        AssertContains(appProject, "<Page Include=\"**/*.xaml\" Exclude=\"App.xaml\" />", "external app explicit page items");
        AssertContains(appProject, "<None Include=\"App.config\" />", "external app explicit app config item");
        AssertContains(appProject, $"<ProjectReference Include=\"../{LibraryAssemblyName}/{LibraryAssemblyName}.csproj\" />", "external app project reference");
        AssertContains(appProject, "<PackageReference Include=\"Extended.Wpf.Toolkit\" Version=\"5.1.2\" />", "external app Xceed Toolkit package reference");
        AssertContains(appProject, "<Resource Include=\"Assets/ExternalResource.txt\" />", "external app WPF resource item");
        AssertContains(appProject, "<Resource Include=\"Assets/ExternalImage.png\" />", "external app WPF image resource item");
        AssertContains(appProject, "<SplashScreen Include=\"Assets/ExternalSplash.png\" />", "external app WPF splash item");
        AssertContains(appProject, "<Content Include=\"Assets/ExternalContent.txt\">", "external app content item");
        AssertContains(appProject, "<CopyToOutputDirectory>PreserveNewest</CopyToOutputDirectory>", "external app content output metadata");
        AssertContains(appProject, "<TargetPath>Assets/ExternalContent.txt</TargetPath>", "external app content target path metadata");
        AssertContains(libraryProject, $"<Project Sdk=\"LibreWPF.Sdk/{SdkVersion}\">", "external library SDK");
        AssertDoesNotContain(libraryProject, $"<Project Sdk=\"{OriginalWpfSdk}\">", "external library original SDK");
        AssertContains(libraryProject, $"<AssemblyName>{LibraryOutputAssemblyName}</AssemblyName>", "external library custom assembly name");
        AssertContains(libraryProject, $"<TargetFrameworks>{ExternalAppTargetFramework}</TargetFrameworks>", "external library Windows target frameworks");
        AssertContains(libraryProject, "<EnableDefaultItems>false</EnableDefaultItems>", "external library explicit item mode");
        AssertContains(libraryProject, "<UseWPF>true</UseWPF>", "external library WPF property");
        AssertContains(libraryProject, "<Compile Include=\"ExternalPanel.xaml.cs\" />", "external library explicit panel code item");
        AssertContains(libraryProject, "<Compile Include=\"ExternalThemedControl.cs\" />", "external library explicit themed control code item");
        AssertContains(libraryProject, "<Compile Include=\"Properties/AssemblyInfo.cs\" />", "external library explicit ThemeInfo code item");
        AssertContains(libraryProject, "<Page Include=\"ExternalPanel.xaml\" />", "external library explicit user-control page item");
        AssertContains(libraryProject, "<Page Include=\"Themes/Generic.xaml\" />", "external library explicit generic theme page item");
        AssertContains(localizationProject, $"<Project Sdk=\"LibreWPF.Sdk/{SdkVersion}\">", "external localization SDK");
        AssertDoesNotContain(localizationProject, $"<Project Sdk=\"{OriginalWpfSdk}\">", "external localization original SDK");
        AssertContains(localizationProject, $"<TargetFramework>{ExternalAppTargetFramework}</TargetFramework>", "external localization Windows target framework");
        AssertContains(localizationProject, "<UseWPF>true</UseWPF>", "external localization WPF property");
        AssertContains(localizationProject, "<LocalizationDirectivesToLocFile>All</LocalizationDirectivesToLocFile>", "external localization directive output");
        RequireFile(Path.Combine(workRoot, LibraryAssemblyName, "Properties", "AssemblyInfo.cs"), "external SDK library ThemeInfo source");
        RequireFile(Path.Combine(workRoot, LibraryAssemblyName, "Themes", "Generic.xaml"), "external SDK library Generic.xaml source");
        RequireFile(Path.Combine(workRoot, LocalizationAssemblyName, "LocalizedView.xaml"), "external SDK localization XAML source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "Assets", "ExternalResource.txt"), "external SDK app WPF resource source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "Assets", "ExternalImage.png"), "external SDK app WPF image resource source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "Assets", "ExternalSplash.png"), "external SDK app WPF splash source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "Assets", "ExternalContent.txt"), "external SDK app copied content source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "App.config"), "external SDK app config source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "ExternalResources.xaml"), "external SDK app merged resource dictionary source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "ExternalPage.xaml"), "external SDK app compiled page source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "ExternalSecondPage.xaml"), "external SDK app second compiled page source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "ExternalLoadComponentView.xaml"), "external SDK app LoadComponent user-control source");
        RequireFile(Path.Combine(workRoot, AppAssemblyName, "ExternalManualLoadComponentView.xaml"), "external SDK app manual LoadComponent user-control source");

        AssertDoesNotContain(appProject, "ProGpuWpfReferenceMode", "external app local artifact mode");
        AssertDoesNotContain(appProject, "ProGpuWpfManagedReferenceRoot", "external app managed artifact root");
        AssertDoesNotContain(appProject, "ProGpuReferenceRoot", "external app ProGPU artifact root");
        AssertDoesNotContain(libraryProject, "ProGpuWpfReferenceMode", "external library local artifact mode");
        AssertDoesNotContain(libraryProject, "ProGpuWpfManagedReferenceRoot", "external library managed artifact root");
        AssertDoesNotContain(libraryProject, "ProGpuReferenceRoot", "external library ProGPU artifact root");
        AssertDoesNotContain(localizationProject, "ProGpuWpfReferenceMode", "external localization local artifact mode");
        AssertDoesNotContain(localizationProject, "ProGpuWpfManagedReferenceRoot", "external localization managed artifact root");
        AssertDoesNotContain(localizationProject, "ProGpuReferenceRoot", "external localization ProGPU artifact root");

        if (File.Exists(Path.Combine(workRoot, "Directory.Build.props")) ||
            File.Exists(Path.Combine(workRoot, "Directory.Build.targets")))
        {
            throw new InvalidOperationException("External SDK smoke must not rely on generated Directory.Build.props or Directory.Build.targets files.");
        }
    }

    private static void ValidateExternalCentralPackageManagementProjectShape(string projectPath)
    {
        string appRoot = Path.GetDirectoryName(projectPath)
            ?? throw new ArgumentException("Project path has no directory.", nameof(projectPath));
        string workRoot = Directory.GetParent(appRoot)?.FullName
            ?? throw new ArgumentException("Project path has no parent directory.", nameof(projectPath));
        string project = File.ReadAllText(projectPath);
        string centralPackages = File.ReadAllText(Path.Combine(workRoot, "Directory.Packages.props"));

        AssertContains(project, $"<Project Sdk=\"LibreWPF.Sdk/{SdkVersion}\">", "external CPM app SDK");
        AssertDoesNotContain(project, $"<Project Sdk=\"{OriginalWpfSdk}\">", "external CPM app original SDK");
        AssertContains(project, $"<AssemblyName>{CentralPackageManagementOutputAssemblyName}</AssemblyName>", "external CPM app custom assembly name");
        AssertContains(project, $"<TargetFramework>{ExternalAppTargetFramework}</TargetFramework>", "external CPM app Windows target framework");
        AssertContains(project, "<UseWPF>true</UseWPF>", "external CPM app WPF property");
        AssertContains(project, "<PackageReference Include=\"System.Reactive\" />", "external CPM app unversioned app package reference");
        AssertDoesNotContain(project, "Version=", "external CPM app project package version metadata");
        AssertContains(centralPackages, "<ManagePackageVersionsCentrally>true</ManagePackageVersionsCentrally>", "external CPM app central package management switch");
        AssertContains(centralPackages, "<PackageVersion Include=\"System.Reactive\" Version=\"6.0.1\" />", "external CPM app central package version");
        AssertDoesNotContain(centralPackages, "LibreWPF.Transport", "external CPM app central WPF transport version");
        AssertDoesNotContain(centralPackages, "LibreWPF.ProGPU", "external CPM app central WPF bridge version");
        AssertDoesNotContain(centralPackages, "ProGPU.DirectX", "external CPM app central ProGPU DirectX version");
        AssertDoesNotContain(centralPackages, "Silk.NET.WebGPU", "external CPM app central Silk WebGPU version");

        string outputAssembly = Path.Combine(
            appRoot,
            "bin",
            "Debug",
            ExternalAppTargetFramework,
            CentralPackageManagementOutputAssemblyName + ".dll");
        RequireFile(outputAssembly, "external CPM app output assembly");
    }

