    private static string SwitchWpfSdkOnly(string normalWpfProject, string description)
    {
        return SwitchWpfSdkOnly(normalWpfProject, OriginalWpfSdk, description);
    }

    private static string SwitchWpfSdkOnly(string normalWpfProject, string originalSdkName, string description)
    {
        string originalSdk = $"<Project Sdk=\"{originalSdkName}\">";
        string proGpuSdk = $"<Project Sdk=\"LibreWPF.Sdk/{SdkVersion}\">";

        AssertContains(normalWpfProject, originalSdk, $"{description} original WPF SDK");
        string switchedProject = normalWpfProject.Replace(originalSdk, proGpuSdk, StringComparison.Ordinal);
        string revertedProject = switchedProject.Replace(proGpuSdk, originalSdk, StringComparison.Ordinal);

        if (!string.Equals(normalWpfProject, revertedProject, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                $"The {description} project changed more than its root SDK during ProGPU SDK switching.");
        }

        return switchedProject;
    }

    private static void ValidateExternalLocalizationDirectives(string workRoot)
    {
        string objRoot = Path.Combine(workRoot, LocalizationAssemblyName, "obj");
        RequireDirectory(objRoot, "external SDK localization obj directory");

        string[] locFiles = Directory
            .EnumerateFiles(objRoot, "*.loc", SearchOption.AllDirectories)
            .OrderBy(static path => path, StringComparer.Ordinal)
            .ToArray();
        if (locFiles.Length == 0)
        {
            throw new InvalidOperationException("Expected external SDK markup compilation to produce localization .loc files.");
        }

        string localizedViewLoc = locFiles.FirstOrDefault(
            static path => string.Equals(Path.GetFileName(path), "LocalizedView.loc", StringComparison.OrdinalIgnoreCase))
            ?? throw new InvalidOperationException(
                "Expected external SDK markup compilation to produce LocalizedView.loc.");
        string locText = File.ReadAllText(localizedViewLoc);

        AssertContains(locText, "ExternalLocalizationRoot", "external SDK localization root directive uid");
        AssertContains(locText, "ExternalLocalizationText", "external SDK localization text directive uid");
        AssertContains(locText, "External localization root comment", "external SDK localization root comment output");
        AssertContains(locText, "External localization text comment", "external SDK localization text comment output");
        AssertContains(locText, "Readable", "external SDK localization readable attribute output");
        AssertContains(locText, "Modifiable", "external SDK localization modifiable attribute output");
        AssertContains(locText, "Unmodifiable", "external SDK localization unmodifiable attribute output");
    }

    private static void ValidateExternalOutput(string outputRoot, string packageFeed)
    {
        RequireFile(Path.Combine(outputRoot, AppOutputAssemblyName + ".dll"), "external SDK app assembly");
        RequireFile(
            Path.Combine(outputRoot, GetAppHostFileName(AppOutputAssemblyName)),
            "external SDK apphost");
        RequireFile(Path.Combine(outputRoot, LibraryOutputAssemblyName + ".dll"), "external SDK library assembly");
        string copiedContentPath = Path.Combine(outputRoot, "Assets", "ExternalContent.txt");
        RequireFile(copiedContentPath, "external SDK copied content output");
        AssertEqual(
            "External SDK copied content text",
            File.ReadAllText(copiedContentPath),
            "external SDK copied content output text");
        string appConfigPath = Path.Combine(outputRoot, AppOutputAssemblyName + ".dll.config");
        RequireFile(appConfigPath, "external SDK app config output");
        string appConfig = File.ReadAllText(appConfigPath);
        AssertContains(appConfig, "<appSettings>", "external SDK app config output appSettings section");
        AssertContains(appConfig, "ExternalSdkAppSetting", "external SDK app config output setting key");
        AssertContains(appConfig, "External SDK app config value", "external SDK app config output setting value");

        foreach (string assemblyName in s_requiredWpfRuntimeAssemblies
                     .Concat(s_requiredProGpuRuntimeAssemblies)
                     .Concat(s_requiredSilkNetRuntimeAssemblies)
                     .Concat(s_requiredSupportRuntimeAssemblies))
        {
            RequireFile(Path.Combine(outputRoot, assemblyName + ".dll"), $"external SDK output asset '{assemblyName}.dll'");
        }

        RequireFile(Path.Combine(outputRoot, "Xceed.Wpf.Toolkit.dll"), "external SDK output Xceed Toolkit asset");
        RequireFile(Path.Combine(outputRoot, "Xceed.Wpf.AvalonDock.dll"), "external SDK output AvalonDock asset");
        RequireFile(Path.Combine(outputRoot, "Xceed.Wpf.AvalonDock.Themes.Aero.dll"), "external SDK output AvalonDock Aero theme asset");
        RequireFile(Path.Combine(outputRoot, "Xceed.Wpf.AvalonDock.Themes.Metro.dll"), "external SDK output AvalonDock Metro theme asset");
        RequireFile(Path.Combine(outputRoot, "Xceed.Wpf.AvalonDock.Themes.VS2010.dll"), "external SDK output AvalonDock VS2010 theme asset");

        foreach (string assemblyName in s_requiredProGpuRuntimeAssemblies)
        {
            ValidateOutputAssemblyMatchesLocalPackage(
                outputRoot,
                packageFeed,
                GetPackageIdForRuntimeAssembly(assemblyName),
                assemblyName,
                "net10.0");
        }

        foreach (string assemblyName in s_requiredWpfRuntimeAssemblies)
        {
            ValidateOutputAssemblyMatchesLocalPackage(
                outputRoot,
                packageFeed,
                "LibreWPF.Transport",
                assemblyName,
                "net10.0");
        }

        RequireAnyFile(outputRoot, GetNativeAssetCandidates("wgpu"), "external SDK output native WebGPU runtime asset");
        RequireAnyFile(outputRoot, GetNativeAssetCandidates("glfw"), "external SDK output native GLFW runtime asset");

        string depsJson = File.ReadAllText(Path.Combine(outputRoot, AppOutputAssemblyName + ".deps.json"));
        AssertContains(depsJson, "LibreWPF.Transport", "external SDK WPF transport package dependency");
        AssertContains(depsJson, "LibreWPF.ProGPU", "external SDK ProGPU WPF package dependency");
        AssertContains(depsJson, "LibreWPF.Interop", "external SDK ProGPU WPF interop package dependency");
        AssertContains(depsJson, "ProGPU.DirectX", "external SDK ProGPU DirectX package dependency");
        AssertContains(depsJson, "ProGPU.Compute", "external SDK ProGPU compute package dependency");
        AssertContains(depsJson, "ProGPU.Transpiler", "external SDK ProGPU transpiler package dependency");
        AssertContains(depsJson, "OpenFontSharp", "external SDK OpenFontSharp package dependency");
        AssertContains(depsJson, "StbImageSharp", "external SDK StbImageSharp package dependency");
        AssertContains(depsJson, "Extended.Wpf.Toolkit", "external SDK Xceed Toolkit package dependency");
        AssertContains(depsJson, "Xceed.Wpf.AvalonDock", "external SDK AvalonDock assembly dependency");
        AssertContains(depsJson, LibraryOutputAssemblyName, "external SDK referenced library dependency");

        ValidateProGpuHiDpiRenderSurface(outputRoot);
    }

